-- Rifts World Book 6: South America - its bestiary and its notable NPCs.
-- 25 creatures (migration 074) and 16 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-south-america-creatures.sql
--
-- WHAT IS HERE:
--   * 9 monsters and spirits with a stat block (playable 0);
--   * the 16 playable R.C.C.s as their NPC view (playable 1). They are also
--     published classes, and their slugs match the class ids, as Madhaven's and
--     New West's playable rows do;
--   * 16 named beings with a stat block.
--
-- A RIFTS BOOK: an M.D.C. being's pool is its main-body M.D.C.; M.D.C. by
-- location, per-level growth and any figure the roll grammar cannot take are in
-- pools_note.
--
-- EXTRACTED by five workers with every number read off a render (the text
-- layer drops minus signs and carries a digit cipher on some pages).
-- RECONCILED by book-reconcile against the renders. Every creature row passes
-- creatureFormulaGaps, the grammar the endpoint rolls with. Prose fields are
-- short paraphrases; an 8-word shingle check against the cache finds none.





-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 25 South America creatures are in' AS assertion, count(*) AS got, 25 AS want
  FROM creatures WHERE slug IN ('giant-vampire-bat', 'loa', 'soul-worm', 'ellal', 'trelque-huecuve', 'huecu', 'aunyain', 'tree-of-wisdom', 'memory-tree', 'jungle-elf', 'lizard-man-lagarto', 'amazon', 'ewaipanomas', 'shaydor-spherian', 'cibola-gatherer', 'pogtalian-dragon-slayer', 'cibola-pincer-warrior', 'grimbor-ape-man', 'felinoid', 'flying-tiger', 'flame-panther', 'hunter-cat', 'oracle-cat', 'sekhmet', 'werejaguar');
SELECT 'and 16 of them are the playable R.C.C.s' AS assertion, count(*) AS got, 16 AS want
  FROM creatures WHERE slug IN ('giant-vampire-bat', 'loa', 'soul-worm', 'ellal', 'trelque-huecuve', 'huecu', 'aunyain', 'tree-of-wisdom', 'memory-tree', 'jungle-elf', 'lizard-man-lagarto', 'amazon', 'ewaipanomas', 'shaydor-spherian', 'cibola-gatherer', 'pogtalian-dragon-slayer', 'cibola-pincer-warrior', 'grimbor-ape-man', 'felinoid', 'flying-tiger', 'flame-panther', 'hunter-cat', 'oracle-cat', 'sekhmet', 'werejaguar') AND playable = 1;
SELECT 'all 16 notable NPCs are in' AS assertion, count(*) AS got, 16 AS want
  FROM notable_npcs WHERE slug IN ('enumu', 'hak-talon', 'king-kryang', 'melastirth', 'stleet', 'bast', 'yaguar-ogui', 'simba', 'inix', 'malkhom', 'iridna', 'rendell', 'kastor', 'kharkon-the-undaunted', 'dalgon-the-undying', 'archill-the-necromancer');
SELECT 'the creatures carry 36 attacks' AS assertion, count(*) AS got, 36 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('giant-vampire-bat', 'loa', 'soul-worm', 'ellal', 'trelque-huecuve', 'huecu', 'aunyain', 'tree-of-wisdom', 'memory-tree', 'jungle-elf', 'lizard-man-lagarto', 'amazon', 'ewaipanomas', 'shaydor-spherian', 'cibola-gatherer', 'pogtalian-dragon-slayer', 'cibola-pincer-warrior', 'grimbor-ape-man', 'felinoid', 'flying-tiger', 'flame-panther', 'hunter-cat', 'oracle-cat', 'sekhmet', 'werejaguar');
SELECT 'and the notables 29' AS assertion, count(*) AS got, 29 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('enumu', 'hak-talon', 'king-kryang', 'melastirth', 'stleet', 'bast', 'yaguar-ogui', 'simba', 'inix', 'malkhom', 'iridna', 'rendell', 'kastor', 'kharkon-the-undaunted', 'dalgon-the-undying', 'archill-the-necromancer');

-- Records this run. See db/migrations/024-data-script-runs.sql.
