INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('giant-vampire-bat', 'Giant Vampire Bats', 'monster', 'rifts', 0, 'Considered an evil predator', '{"IQ":"1D4+2","ME":"1D4+18","MA":"1D6+9","PS":"1D6+20","PP":"1D6+16","PE":"1D6+16","PB":"1D4+6","Spd":"3D6+20"}', NULL, NULL, '2D6x10', '6', NULL, 'Spd 3D6+20 is flying; 3D6 on the ground or climbing. The book prints the third attribute as "M.D." (read as M.A.). Group size: 1D4+1 in the wild, 2D6 to 1D6x10 in a cave, 1D4+5 when sent by the vampires.', NULL, 14, '{"attacks":4,"initiative":1,"strike":3,"parry":4,"dodge":4}', 'Plus 6 to dodge while flying (instead of 4); plus 3 to save vs magic and psionics. In sunlight: 2 off initiative, strike, parry and dodge, and melee attacks halved. Torches and flashlights spook it as Horror Factor 10, a spotlight in the face or a globe of daylight as 15. Silver does mega-damage to it (wood and water do not); ordinary M.D. weapons do half, magic does full.', 'Tracking by scent 85%; identifying one particular scent 80%; tracking, striking and dodging by hearing 65%; climbing trees, walls and cave sides 75%; swimming only 30% (keeps away from deep water).', 'Heals 1D6 M.D. each melee round; poison, disease and S.D.C. weapons cannot harm it; half damage from non-magical M.D. attacks; radar sense 1200 ft that maps people, objects and movement and reveals invisible targets; smells blood up to 2 miles; flight is magical rather than physical. Master vampires and vampire intelligences can command (but not summon) them.', 'None', 'None', '5 feet (1.5 m) tall, 6 foot (1.8 m) wingspan', '200 lbs (90.6 kg)', '20 to 30 years', 'Forests, jungles and mountains of South America; roosts in caves, ruins and other dark places', 'Serves the vampires of Haktla (over 10,000 in its flock)', NULL, NULL, 'A D-Bee monster: a near man-sized, heavy-bodied bat with stubby wings that flies by magic, hunts live prey at night and tears flesh rather than sipping blood. Its origin is unknown; it is found only in South America, and the Vampire Kingdom of Haktla sends flocks of them against Colombia.', 'Rifts World Book 6: South America p.41-42'),
('loa', 'Loas (Ghostly and Divine)', 'spirit', 'rifts', 0, 'Any; most are good or selfish', '{"PS":"N/A","PP":"N/A","PE":"N/A","PB":"N/A","Spd":"22"}', NULL, NULL, '1D4x10+40', '1D4+4', NULL, 'ONE stat block covers both kinds; the stored figures are the Ghostly Loa (90% of loas). Its I.Q., M.A. and M.E. are those of the dead person it imprints on, so they are not stored; physical attributes do not apply in energy form. Divine Loa: I.Q. 18, M.A. 17, M.E. 17, fly speed 33, P.P.E. 1D6+6, I.S.P. equal to P.P.E. x10, Horror Factor 12. Ghostly Loa I.S.P. is printed as its P.E. x6 (no P.E. in energy form, so not stored). Spd is hover/flight. A minor M.D.C. being on Rifts Earth; In S.D.C. settings: S.D.C. 1D4x10, hit points 5D6 in energy form. Needs 40 P.P.E. a week (divine 60).', NULL, 10, '{"attacks":5,"initiative":2,"strike":2,"parry":4,"dodge":4,"roll":2,"pull":2}', 'Horror Factor 12 for a divine loa. Attacks are psionic in energy form, physical or psionic in a host. Plus 3 to save vs magic and psionics, plus 10 vs Horror Factor; bonuses apply in both forms. Possession is resisted by a save vs psionics (a willing host does not save).', 'A ghostly loa keeps whatever skills and languages its dead person had. A divine loa: Creole, French, Spanish and every African tongue at 98%; Voodoo Lore and Demon/Monster Lore 98%; Prowl 88%; tracking of animals and humans 76%; Wilderness Survival 72%; W.P. Blunt and W.P. Spear.', 'Invisible, intangible energy being harmed only by magic and psionics; flies and passes through solid matter; can show itself as a faint ghostly image (a divine loa as a vague winged humanoid); imprints on a dead human or D-Bee and takes on its identity and strongest memories; possesses humans, D-Bees and animals (not supernatural beings), granting the host +2D4 P.S., +1D6 P.P., +2D4 P.E. and 100 bonus S.D.C. while it rides them; feeds on P.P.E. (divine loas only on ritual and ley line P.P.E.).', 'None', 'Ghostly: two super psionic powers suited to the dead person (or one super plus two sensitive or healing powers), at 6th level mind melter strength. Divine: two sensitive or healing powers plus a god-set pair - Legba: Hydrokinesis, Mind Bond; Ertzuli: Empathic Transmission, Hypnotic Suggestion; Danbhala: Bio-Manipulation, Mind Bond; Chango: Pyrokinesis, Psi-Sword; Oggun: Telemechanics, Psi-Sword.', 'Roughly 5 ft (1.5 m) in energy form', 'Not applicable', NULL, 'Anywhere believers in Voodoo live: mostly South America and Africa''s west coast, some in North America', 'Voodoo priests and believers; divine loas serve their Voodoo god', 'Other entities and supernatural creatures', 'Not for player characters (NPC only, per the book).', 'The lesser spirits of Voodoo. A ghostly loa is an entity that believes it is the spirit of a particular dead person and guards or torments the living accordingly; a divine loa is an agent of one Voodoo god and feeds only on ceremonial P.P.E. Both possess hosts to act in the physical world.', 'Rifts World Book 6: South America p.53-54'),
('soul-worm', 'Soul Worms', 'monster', 'rifts', 0, 'Anarchist (33%), evil (64%), unprincipled or good (3%)', '{"IQ":"2D6+18","ME":"1D6+20","MA":"1D6+20","PS":"4D6+26","PP":"4D6+4","PE":"2D6+18","PB":"1D6","Spd":"2D4x10"}', NULL, NULL, '4D6x1000', '1D4x1000', '1D6x100', 'P.P. is printed twice, 4D6+4 and 1D6+20 (stored: the first). The eye has 1/100 of the main M.D.C.; each of the 12 tentacles has 60. M.D.C. only in magic-rich places such as Rifts Earth; In S.D.C. settings: S.D.C. 2D6x1000, hit points 1D4x1000. Loses 1D4x10 M.D.C. (not regenerated) each week it goes without draining a victim. Average level of experience 2D6+3.', NULL, 15, '{"attacks":6,"initiative":1,"strike":2,"parry":1,"dodge":1}', 'Plus 1 to save vs magic and psionics, plus 6 vs Horror Factor; cannot be possessed or mind controlled. An unfed addict is -2 to strike, parry, dodge and save vs psionics. No damage table is printed for the species.', 'Understands every language by magic and is literate in ten. Demon/Monster Lore +25%; Intelligence and Swimming +20% each; Detect Concealment and Detect Ambush +15% each; six more skills of choice at +10%.', 'Nightvision 500 ft; sees the invisible and turns invisible at will; fire and plasma (even M.D.) do no damage; bio-regenerates 2D6x10 M.D.C. per melee round; teleports up to 100 miles; dimensional teleport 72% to known dimensions; tentacles handle objects almost like hands. Soul Drain: while it concentrates (helpless for 2D4 minutes) a victim who fails a save vs psionics is stripped of 3D6 of both P.P.E. and I.S.P. each round, then 1D4 M.E. a round (saves at -2); at M.E. zero the victim dies and the worm keeps his memories for a while. Most evil ones must drain someone weekly.', 'Every spell of levels 1-4, and two more of any level at each new experience level; all cast at 6th level strength.', 'All sensitive powers plus four super psionic powers of choice, at 8th level.', '5-7 ft (1.5-2.1 m) tall; 25-30 ft (7.6-9.1 m) long', 'Four to seven tons', NULL, 'Scattered across the Megaverse; Inix rules Cibola', 'Serve demon lords and evil gods; keep company with temporal raiders, sowki, mindolars, demigods and godlings', NULL, 'Written like an R.C.C., but the book rules them out as player characters (NPC only). Wealth: 4D6x100 million credits plus 2D6 billion hidden in valuables; takes no cybernetics.', 'Huge fleshy worms with one great eye ringed by twelve tentacles, once the secret police of a vanished alien intelligence. A few thousand survive; they are psychic vampires that strip victims of memory and life, making them feared interrogators.', 'Rifts World Book 6: South America p.128-129'),
('ellal', 'Ellal', 'undead', 'rifts', 0, 'Diabolic only', '{"IQ":"3D6+2","ME":"3D6+3","MA":"3D6","PS":"4D6+6","PP":"3D6+4","PE":"4D6+6","PB":"3D6","Spd":"1D4x10"}', NULL, NULL, 'PEx10', NULL, NULL, 'Stored figures are the animated corpse form. Energy form: I.Q. 2D6+3, floating Spd 2D6x10, all other attributes not applicable, Horror Factor 8. Each century of undead life adds 1D6x10 M.D.C., +1D4 P.S., +1 P.E. and +1 P.P. P.S. and P.E. are supernatural. In S.D.C. settings: S.D.C./hit points P.E. x10 plus 1D4x10 per century. Reduced to -21 it falls into a regenerative coma; only -200 M.D.C. or an exorcism during the coma destroys it. Starving costs 1 P.B. a month and 1 P.S. and 1 P.E. every two months. Average level 2D4 (age 100 to 400 years). No P.P.E. is printed.', NULL, 12, NULL, 'Horror Factor 12 only once revealed as undead (8 in energy form, 15 once P.B. falls to 3). Normal weapons, M.D. ones included, do one-third damage; silver does mega-damage; triple damage comes from holy weapons, anti-undead bio-weapons, and Millennium Tree wands or staves. No attacks per melee, combat bonuses or damage table are printed.', 'Has the skills the body had in life, starting at first level and rising one level per fifty years in that body; also any magic or psionics the dead person had. Most choose the bodies of mages and psychics.', 'Possesses a corpse and keeps it from decaying while it murders at least one living victim a month; heals 1D4x10 M.D.C. each melee round; has supernatural P.S. and P.E.; illusions do not fool it; unharmed by daylight; may sleep in stasis for centuries when imprisoned. In energy form it is invisible, incorporeal and immune to normal weapons. Banishment drives it from the body, which then rots.', 'As the possessed body had in life', 'As the possessed body had in life', 'Varies with the body it inhabits', NULL, 'Effectively immortal while it feeds; some are 400-600 years old', 'South America, concentrated along its ley lines', NULL, 'The Aunyain see them as rivals', NULL, 'Diabolic entities that inhabit the dead of South America, gaining the corpse''s memories and growing stronger with every century. The oldest rival demon lords and are worshipped as god-kings.', 'Rifts World Book 6: South America p.148-149'),
('trelque-huecuve', 'Trelque-huecuve', 'monster', 'rifts', 0, 'Considered an evil predator', '{"IQ":"1D4","ME":"1D6+2","MA":"1D4","PS":"1D6+40","PP":"1D4+16","PE":"1D4+20","PB":"1D6","Spd":"2D6+20"}', NULL, NULL, '400', '9', NULL, 'M.D.C. by location: Mouth/Beak 80, Tentacles (10) 100 each (300 for giants), Main Body 400 (900 for giants). Spd is swimming.', NULL, 12, '{"attacks":10,"initiative":1,"strike":4,"parry":5,"dodge":4}', 'Horror Factor 16 for giants. Up to five attacks per melee on any one target, ten in all. Dodge is +4 with the tentacles, +1 with its whole body. Giants add 5 to damage (the book prints "+5 M.D.C.") and are big enough to pull small boats under.', 'Senses movement underwater 88%.', 'Senses motion, temperature change and current in the water; keen hearing; a fast swimmer; lives in fresh or salt water.', 'None', 'None', '30 to 300 feet (9.1 to 91 m) long', '600 lbs to 5 tons', 'Unknown; believed to be centuries', 'Large rivers, seas and oceans; most common at the Amazon''s mouths, the Demon Sea (Bermuda Triangle) and the South Atlantic coasts of Brazil, Argentina and west Africa', 'None; solitary', 'Giant predators and humanoids', NULL, 'A ten-tentacled monster squid of native legend that waits on the river bottom and snatches anything that stirs the water above it, hauling the victim down to its beak. It is not a true squid.', 'Rifts World Book 6: South America p.149-150'),
('huecu', 'Huecu', 'monster', 'rifts', 0, 'Considered an evil predator', '{"IQ":"1D6","ME":"1D6+10","MA":"1D6","PS":"2D6+30","PP":"1D6+14","PE":"1D6+16","PB":"1D4","Spd":"2D4x10"}', NULL, NULL, '225', '10', NULL, 'Main Body 225 M.D.C. (stored); the stinger/tail has 60. Spd 2D4x10 is underwater; flying 5D6, for only 1D6 minutes at a time and clumsily among dense trees.', NULL, 11, '{"attacks":4,"initiative":1,"strike":5,"automatic_dodge":5}', 'Strike +5 underwater, +4 from the air. Automatic dodge +5 underwater, +3 flying. Cannot parry.', NULL, 'Nightvision 200 ft; can glide on air currents and fly short distances; poisonous stinger.', 'None', 'None', '60 feet (18.3 m) long, 40 foot (12.2 m) wingspan', '1000 to 2000 lbs (450 to 900 kg)', '60 years', 'Rivers', 'None; solitary', 'Humanoids, the trelque-huecuve, other monsters and giant predators', NULL, 'A giant carnivorous freshwater manta ray out of myth that prefers intelligent prey, possibly a P.P.E. feeder. Tribes hunt it for its long-keeping meat, and its teeth make blades that can parry M.D. weapons.', 'Rifts World Book 6: South America p.150'),
('aunyain', 'Aunyain', 'monster', 'rifts', 0, 'Diabolic or Miscreant', '{"IQ":"4D6","ME":"3D6","MA":"3D6","PS":"3D6+4","PP":"3D6","PE":"4D6","PB":"2D6","Spd":"4D6"}', NULL, NULL, '3D6x10', NULL, NULL, 'M.D.C. plus 10 per level of experience. P.S. and P.E. are supernatural. Average level of experience 1D4+2. No P.P.E., attacks per melee or damage table are printed.', NULL, 13, '{"initiative":1}', 'Plus 3 to save vs magic and psionics, plus 4 vs Horror Factor; cannot be possessed or mind controlled. Energy attacks do half damage.', 'Skills as the Totem Warrior O.C.C.', 'Shadow meld at will (as the spell); half damage from energy; sees in total darkness 400 ft; sees the invisible; changes into a giant tapir at will; heals 1D6 M.D.C. each melee round.', 'Starts with six spells (levels 1-4) and gains two more (levels 1-8) at each new experience level.', 'None', '6-10 ft (1.8-3.0 m)', '300 to 600 lbs (135 to 270 kg)', NULL, 'The Amazon rain forest (over 2,000; 3D6x100 on the east bank in families of 1D6+1), plus 1D6x100 around the Yucatan, Mexico and the American south and west', 'Sometimes necromancers, goqua, sowki and other supernatural beings; serve the god Aunyaina', 'Vampires and the ellal (rivals for victims)', 'R.C.C.-shaped entry with no player-character note and no experience table; entered as NPC-only. Carry no equipment and rely on magic.', 'Tusked boar-headed sorcerers: humans transformed by the alien god Aunyaina in exchange for human sacrifices. They form jungle cults, raid settlements for victims, and sometimes rule tribes as gods.', 'Rifts World Book 6: South America p.152'),
('tree-of-wisdom', 'Trees of Wisdom', 'plant', 'rifts', 0, 'Usually Scrupulous or Principled; fewer than 3% selfish or evil', '{"IQ":"2D6+18","MA":"2D6+18","ME":"2D4+20","PE":"2D4+20","PS":"N/A","PP":"N/A","PB":"N/A","Spd":"N/A"}', NULL, NULL, '3D6x100+300', '3D4x100', '2D6x100+100', 'M.D.C. is the main trunk; each branch has 2D4x10. P.P.E. plus whatever it draws from ley lines. Other physical attributes are printed as meaningless. A dying tree loses 1D6x10 M.D.C. an hour after putting its essence in an acorn (100 M.D.C.). No Horror Factor is printed.', NULL, NULL, '{"attacks":3}', 'Plus 2 to save vs magic and psionics, plus 10 vs Horror Factor. Its three attacks are spells or psionics only; making an acorn takes one melee round.', 'The equivalent of 98% in most lores and general knowledge; expert in herbology, holistic medicine, law, politics and psychology; understands magic, ley lines and psionics; knows little technology.', 'Senses its surroundings without sight (2000 ft for people and animals, 20 miles for disasters, ley line surges and Rifts); bio-regenerates 4D6x10 M.D.C. a minute; free telepathy with any intelligent being within 2000 ft; immune to ordinary fire, heat and cold (half from M.D. versions); needs no air, water or food, living on ley line P.P.E.; can pour its mind into an acorn to be replanted. Never grows within 1000 miles of a Millennium Tree.', 'As a 10th level Ley Line Walker: Armor of Ithan; Banishment; Call Lightning; Calling; Calm Storms; Chameleon; Close Rift; Cloud of Smoke; Concealment; Constrain Being; Domination; Energy Disruption; Energy Field; Fear; Globe of Daylight; Globe of Silence; Horrific Illusion; Ley Line Transmission; Magic Net; Negate Magic; Oracle; Purification; Summon and Control Animals; Summon Rain; Turn Dead; Wisps of Confusion; Words of Truth.', 'As a 10th level Mind Melter: every sensitive power; Mind Wipe; Telekinetic Force Field; Bio-Manipulation; Mind Bolt; Hypnotic Suggestion; Group Mind Block; Telekinesis; Mind Block Auto-Defense; Empathic Transmission.', '10 to 50 feet (3 to 15.2 m) tall; leaves 3 to 12 feet long', NULL, NULL, 'Maga Island (a council of 48 around a nexus) and several dozen elsewhere in South America, in groves of 2-24 near ley lines; possibly Florida', 'Jungle elves, biomancers, Voodoo priests; command the Memory Trees', NULL, NULL, 'Intelligent telepathic trees with segmented trunks that rule Maga Island as the Tree Council and advise jungle elves and biomancers across the continent. Legend says the wisest elves may become one at death.', 'Rifts World Book 6: South America p.58-59'),
('memory-tree', 'Memory Trees', 'plant', 'rifts', 0, 'Always Principled', '{"IQ":"3D6","MA":"3D6","ME":"1D4+20","PE":"1D4+20","PS":"N/A","PP":"N/A","PB":"N/A","Spd":"N/A"}', NULL, NULL, '1D4x100', NULL, '1D4x100', 'M.D.C. is the main body; each average branch has 1D4x10. Other physical attributes are printed as meaningless. No P.P.E. or Horror Factor is printed.', NULL, NULL, '{"attacks":2}', 'Plus 1 to save vs magic and psionics, plus 6 vs Horror Factor. Its two attacks are psionic.', '98% in a range of lores (Magic Lore among them), languages, astronomy, anthropology, botany, math and wilderness skills; cannot learn or teach spell casting, circles, wards, biomancy or summoning.', 'Senses its surroundings without sight to 1000 ft; bio-regenerates 1D6x10 M.D.C. a minute; free telepathy to 1000 ft; immune to ordinary fire, heat and cold (half from M.D. heat and cold); trades memories and knowledge mind to mind with a willing student (a mind block stops it); consults other Memory Trees within 200 ft; can store its mind in an acorn.', 'None', 'Every sensitive power; also Empathic Transmission and Bio-Manipulation.', NULL, NULL, NULL, 'Maga Island and other jungle elf communities', 'Jungle elves; obey the Trees of Wisdom', 'The Splugorth, who try to extract their memories', NULL, 'Spindly spiral-trunked trees that serve Maga as living libraries and teachers, recording the memories of willing students and teaching by direct mental transfer. They hold the jungle elves'' history from the Green World.', 'Rifts World Book 6: South America p.59-60'),
('jungle-elf', 'Jungle Elf', 'humanoid', 'rifts', 1, 'Any', '{"IQ":"3D6+2","ME":"3D6","MA":"4D6","PS":"2D6+3","PP":"3D6+3","PE":"3D6","PB":"4D6","Spd":"4D6"}', NULL, '20', NULL, 'PE+1D4x10', 'ME+1D4x10', 'Hit points are not printed; they come with the O.C.C. S.D.C. 20 is the racial figure, added to O.C.C. and skill S.D.C. M.D.C. only from armor or magic. P.P.E. +1D6 and I.S.P. +2D4 per level of experience.', NULL, NULL, NULL, '+1 to save vs magic and vs psionic attack, +2 to save vs Horror Factor.', 'Wilderness Survival from 55% at level one; Dragonese/Elven +25% and Faerie +20% on top of O.C.C. languages; three in four are trained archers.', 'Empathic link with nearby plants and animals (120 ft): sees brief sensory flashes of what they experienced, and can soothe an angry animal (40% +4% per level, not supernatural beasts). Gift of Nature: for 8 P.P.E. makes an edible fruit on a living plant that feeds one person a day, a limited number per plant; overreaching hurts the plant (2D6 S.D.C.) and the elf (1D4x10 S.D.C. backlash). Cybernetics strip its powers and halve P.P.E.; biomancy fades in those who turn to machines.', 'Biomancy: one level-one spell at level 2, then one more each level, of a spell level up to experience level minus one. Warlock, Mind Melter and Shifter elves have none.', 'Major psionic: six powers from Sensitive, Physical or Healing.', NULL, NULL, NULL, 'The Amazon rain forest, above all Maga island; wanderers turn up across South America and beyond', NULL, NULL, 'Biomancer 20%, Wilderness Scout 15%, Warlock 15% (Fire only 0.5%), Ley Line Walker 10%, Herbalist/Druid 10%, Mind Melter 10%, Mystic 5%, Shifter 3%, Totem Warrior 3%, Jungle Shaman or African Priest 3%, Rain Maker or Medicine Man 2%, Stone Master 2%, Temporal Wizard 2%', 'Forest-dwelling elves who call themselves the children of the Tree of Life, living in nomadic bands or grown cities of living trees; Maga island is their greatest community, and they shun machines as dead things.', 'Rifts World Book 6: South America p.57-58'),
('lizard-man-lagarto', 'Lizard Man of Lagarto', 'humanoid', 'rifts', 1, 'Any', '{"IQ":"3D6","ME":"2D6","MA":"3D6","PS":"3D6","PP":"3D6","PE":"3D6","PB":"3D6","Spd":"3D6"}', 'PE+1D6', '1D6x10', NULL, '2D6', NULL, 'Hit points standard (P.E. +1D6 per level). A Lagarto army soldier adds 3D6 S.D.C. Spd is running and climbing; swimming speed is double. Psionics standard (no I.S.P. printed).', NULL, 13, '{"initiative":1}', 'Horror Factor only in an attack frenzy. In water it gains +2 dodge and +1 each to strike and parry. Soldiers of Lagarto add +1 to strike and parry in any fight.', 'Swim 90% as a natural ability; skills otherwise by O.C.C. Traditional lizard men know little technology.', 'Breathes water indefinitely, polarized vision, swims at 90%.', 'By O.C.C. only.', 'Standard.', '4.5 to 5.5 ft (1.4 to 1.7 m)', '80 to 150 lbs (36 to 67.5 kg)', '50 years', 'Rivers, streams, swamps and lakes', NULL, NULL, 'Any O.C.C. except Borgs and Coalition military; a Lagarto army soldier counts as a Headhunter, Wilderness Scout or Special Forces soldier', 'Green-scaled reptilian humanoids with a spiny crest down the tail and a mouth of small sharp teeth, split between reclusive traditional hunters and the militant, better-equipped soldiers of New Dragcona.', 'Rifts World Book 6: South America p.79'),
('amazon', 'Amazon', 'humanoid', 'rifts', 1, 'Any, but usually good, Unprincipled or Aberrant', '{"IQ":"3D6","ME":"3D6+4","MA":"3D4","PS":"3D6+10","PP":"3D6+8","PE":"4D6+4","PB":"3D6+6","Spd":"6D6"}', 'PE+1D6', '4D6x10', '3D6x10', '1D4x10', 'ME+1D6x10', 'Hit points as a human (P.E. +1D6 per level). The 4D6x10 S.D.C. applies in non-M.D.C. settings; on Rifts Earth she is an M.D.C. being with 3D6x10 +2D4 per level. Pools shown are the psionic option (P.P.E. 1D4x10; I.S.P. M.E. +1D6x10, +2D6 per level). The magic option instead has P.P.E. 2D4x10 + P.E., +2D6 per level, and I.S.P. M.E. +3D6. Supernatural P.S. and P.E. Bio-regenerates 1D4x10 M.D. an hour.', NULL, NULL, '{"attacks":5,"initiative":2,"parry":1,"dodge":1}', 'Attacks are Hand to Hand: Expert (four at level one) plus the racial +1. +1 to save vs magic, +4 vs Horror Factor, +3 vs disease, +10% vs coma/death. Psionic option adds +1 vs psionics, +2 vs magic illusions, +1 vs Horror Factor.', 'Languages Atlantean and Spanish at 98% plus two of choice (+10%); Lore: Monsters & Demons (+15%); tracking of animals and of humans (each +15%); Land Navigation and Wilderness Survival (each +10%); W.P.s Archery and Targeting, Energy Rifle, Sword and two more; Hand to Hand: Expert (Martial Arts, or Assassin if evil, for one other skill); six other skills plus one at levels 3, 6, 9 and 12; four secondary skills.', 'Nightvision 60 ft, keen hawk-like sight, M.D. heat and cold do half damage and ordinary heat and cold none, bio-regenerates 1D4x10 M.D. per hour, supernatural strength and endurance; no aging until about 200 and a life of 1D4x100+160 years.', 'Magic option: the Mystic''s magic powers 1, 2 and 4, plus four lesser psionic powers (Healing, Sensitive or Physical) as a major psionic.', 'Psionic option: master psionic with Psi-Sword and Psi-Shield and eight lesser powers, two more lesser powers per level, and a further super power at every odd level from 3 through 13.', 'Average 6 ft (1.8 m), up to 7 ft (2.1 m)', '140 to 160 lbs (63 to 72 kg)', '1D4x100+160 years', 'Manoa, and independent human-Amazon communities across South America', NULL, NULL, 'R.C.C. with its own skills; no O.C.C.; choose magic or psionics', 'Superhuman women warriors descended from a tribe the Atlanteans rescued and remade, sworn defenders of Manoa: honest, blunt and fierce, scornful of cowardice and lies. Daughters inherit the powers; sons take after the father.', 'Rifts World Book 6: South America p.97-99'),
('ewaipanomas', 'Ewaipanomas', 'alienhumanoid', 'rifts', 1, 'Any', '{"IQ":"3D6","ME":"3D6+4","MA":"3D6","PS":"2D6+20","PP":"3D6","PE":"4D6+4","PB":"2D6","Spd":"3D6"}', 'PE+1D6', '1D6x10+10', '2D6x10', '1D4x10', NULL, 'Hit points standard in non-M.D.C. worlds, with 1D6x10+10 S.D.C., to which O.C.C. and skill S.D.C. are added. In a mega-damage setting such as Rifts Earth: 2D6x10 M.D.C., +1D6 per level. The 1D4x10 P.P.E. is added to the O.C.C.''s. Supernatural P.S. and P.E. Regenerates 2D6 M.D.C. per hour.', NULL, NULL, NULL, 'Saves: +2 each vs magic, psionics and Horror Factor. These stack with attribute and O.C.C. bonuses.', 'By O.C.C.', 'Supernatural strength, regenerates 2D6 M.D.C. an hour, speaks with elementals (98%). Never takes cybernetics.', 'By O.C.C.; most are Earth Warlocks or Stone Masters.', NULL, '6 to 7 ft (1.8 to 2.1 m)', '300 lbs (135 kg)', NULL, 'The Amazon jungle; most now live in Manoa as builders and architects', NULL, NULL, 'Earth Warlock 70%, Stone Master 20%, other 10%; average level 1D4, advancing at half the normal rate', 'The Headless Men of explorer legend: aliens stranded by the Atlantean disaster, with eyes in the shoulders and a mouth in each breast. Calm, logical and peaceable, but fearsome when roused by cruelty or the threat of slavery.', 'Rifts World Book 6: South America p.102-103'),
('shaydor-spherian', 'Shaydor Spherian', 'alien', 'rifts', 1, 'Any', '{"IQ":"3D6+2","ME":"4D6+2","MA":"3D6+2","PS":"2D6","PP":"2D6","PE":"3D6+2","PB":"3D6","Spd":"3D6"}', NULL, NULL, '2D4x10+20', NULL, 'ME+3D6x10', 'I.S.P. depends on the psionic orientation, each +10 per level: Healer M.E. +4D6x10, Sensitive and Explorer M.E. +3D6x10 (shown), Warrior M.E. +4D4x10.', NULL, 12, '{"initiative":4,"strike":3,"parry":3,"dodge":4,"roll":2}', '+5 to strike with the tail; +2 to roll also covers falls and impact. Saves: Horror Factor +6; psionics, poison and disease +1 each; coma/death +10%. All stack with attribute bonuses.', 'Math, Basic and Advanced (+20% each); Writing (+10%); Art (+5%); Computer Operation (+10%); Wilderness Survival (+10%); Land Navigation (+15%); Shaydorian and Dragonese/Elf 98%, two more languages +20%, W.P. Knife and one W.P.; seven other skills plus one at levels 3, 6, 9 and 12; six secondary skills. Swim 50%, climb 70%, prowl 60% as natural abilities.', 'Prehensile feet, tail and tentacles, double-jointed and ambidextrous, good color vision and keen hearing; prowl 60%, climb 70%, swim 50%.', 'None; may collect and use magic items.', 'Master psionic in one of four orientations. Healer: seven set powers plus five Healing, three Sensitive, three Super. Sensitive: seven set powers plus six Sensitive, two Healing, two Physical, three mind-type Super. Explorer: nine set powers plus four Physical, two Sensitive, three Super. Warrior: nine set powers plus four Physical, two kinesis Super, three other Super. Further powers every two or three levels.', '7 to 10 ft (2.1 to 3.0 m)', '100 lbs (45 kg)', NULL, 'Manoa, where they are a large and influential population; elsewhere in small traveling groups or as slaves', NULL, NULL, 'R.C.C.; the psionic orientation (Healer, Sensitive, Explorer or Warrior) serves as the O.C.C.', 'Gentle, long-limbed crystalline D-bees long enslaved by the Splugorth; a wandering tribe settled in Manoa two centuries ago and the race has since flourished there. Fully described in Rifts Atlantis.', 'Rifts World Book 6: South America p.103'),
('cibola-gatherer', 'Gatherer (Cibola)', 'alien', 'rifts', 1, 'Any; at best Unprincipled, most Anarchist, Miscreant or Diabolic; those serving Inix are Anarchist or Miscreant', '{"IQ":"4D6","ME":"3D6+4","MA":"3D6","PS":"2D6+20","PP":"3D6+2","PE":"2D6+10","PB":"2D6","Spd":"4D6"}', '1D6x10', '1D4x100+100', '1D4x100+200', '3D6x10+PE', 'ME+2D4x10+30', 'M.D.C. is the carapace on Rifts Earth and other magic-rich worlds; the hit points and S.D.C. apply only in S.D.C. environments. P.P.E. +2D6 and I.S.P. +3D6 per level. Bio-regenerates 1D4 M.D.C. an hour. Supernatural P.S. and P.E. Average NPC level 2D4+1.', NULL, 13, '{"attacks":5,"strike":2,"parry":3,"dodge":3,"roll":1}', 'Attacks per melee: 5 in hand to hand combat, 3 when using psionics, 2 when casting magic. Saves: magic +2, psionics +3. Teleporting takes a melee round and defends at -2.', 'Lores: Demon (+25%) and D-Bee (+20%); tracking of humans and of animals, Land Navigation and Wilderness Survival (+20% each); Basic Math (+15%); Dragonese/Elf at 98% plus five languages (+20%); three W.P.s; eight other skills (+10%), often rogue skills.', 'Nightvision 200 ft, sees the invisible, can become invisible at will, heals 1D4 M.D.C. an hour. Dimensional teleport: 88% to a well-known world, 64% to one visited once, 32% blind, each +2% per level to 98%.', 'Four spells of levels 1-4 at first level, then one per level of up to its own level; more can be bought or learned.', 'Four powers from any category including super at level one (Mind Wipe, Psi-Sword and Possess Others only after level 3), two more per level.', '4 to 6 ft (1.2 to 1.8 m)', '200 to 500 lbs (90 to 225 kg)', '3,000 years', 'Cibola and the dimensions its bands raid; patrols into the Amazon rain forest and northern islands', NULL, NULL, 'R.C.C. with its own skills; not recommended for players', 'Squat, four-armed dimension-hopping scavengers, part toad and part lobster, with a small six-fingered pair of hands and a larger clawed pair. Inix uses them as thieves, spies, slave-takers and Cibola''s security scouts.', 'Rifts World Book 6: South America p.134-135'),
('pogtalian-dragon-slayer', 'Pogtalian Dragon Slayer', 'giant', 'rifts', 1, 'Any, but leans Anarchist; most in Cibola are Anarchist or Miscreant', '{"IQ":"3D6+1","ME":"4D6","MA":"3D6","PS":"5D6+10","PP":"4D6+2","PE":"4D6+6","PB":"1D6+1","Spd":"4D6"}', 'PEx5+1D6', '1D4x100', '1D4x100', NULL, NULL, 'Hit points (P.E. x5, +1D6 per level) and S.D.C. apply in S.D.C. environments; on Rifts Earth an M.D.C. being. Energy aura adds 100 M.D.C., taken first and restored in 24 hours. Special bio-regeneration restores 1D6x10 M.D.C. three times a day. Attributes are supernatural.', NULL, 12, '{"attacks":5,"initiative":3,"parry":1,"dodge":2}', 'Attacks are Hand to Hand: Martial Arts (four at level one) plus one for great strength and agility. The initiative, parry and dodge come from supersensitive hearing. +3 to save vs magic, +3 vs psionic attack, +5 vs Horror Factor.', 'Hunting, Wilderness Survival +25%, Land Navigation +20%, Track Animals +20% (dragons and dinosaurs too), Skin and Prepare Animal Hides +20% (+10% for small animals), Swimming +10%, Hand to Hand: Martial Arts; W.P.s Blunt, Targeting and two of choice; six other skills plus two at levels 3, 6, 9, 12 and 15.', 'Impervious to magic fire (dragon fire included) and to normal fire and cold; regrows lost teeth; an unhinging jaw for huge bites. The energy aura switches on with fear, anger or exertion and makes held S.D.C. weapons strike with the giant''s punch damage.', NULL, NULL, '3D6+10 ft', '1D6x1000 lbs (1D6x450 kg)', '300 years', 'Pogtalia, a jungle world ruled by dragons; in the Cibolan defense forces, and deserters in the Amazon', NULL, NULL, 'R.C.C. with its own skills; Pilot, Rogue and Pilot Related skills only if trained in Cibola', 'Proud giant D-bees bred to hunt dragons, serving Inix as mercenaries and rivals of the pincer warriors. They seek great foes rather than loot, but eat humanoids, which earns them a monstrous name.', 'Rifts World Book 6: South America p.135-136'),
('cibola-pincer-warrior', 'Pincer Warrior (Cibola)', 'insectoid', 'rifts', 1, 'Anarchist or evil', '{"IQ":"2D6+2","ME":"3D6","MA":"3D6","PS":"4D6+20","PP":"3D6+8","PE":"3D6+12","PB":"1D6+2","Spd":"1D6x10"}', '1D4x100', '5D6x10', '4D6x10+60', NULL, NULL, 'Hit points and S.D.C. apply in non-M.D.C. worlds. On Rifts Earth M.D.C. 4D6x10+60, +1D4x10 per level. Bio-regenerates 1D4x10 M.D.C. every five minutes. Supernatural P.S. and P.E. Grows 1 inch and 20 lbs per level after the first.', NULL, 13, '{"attacks":4}', 'Hand to Hand: Assassin; four attacks at level one, more by that table. Half damage from all energy attacks, magic energy included.', 'Detect Ambush and Detect Concealment (+10% each); Prowl, Wilderness Survival and tracking of humans or animals (+15% each); Climb (+10%); Demongogian and Dragonese/Elven at 98% plus two languages (+10%); two W.P.s; one physical or wilderness skill at levels 4, 8 and 12. Most cannot swim.', 'Nightvision 1000 ft, regrows limbs in 1D4 days, half damage from energy; a carnivore that can fast for months. Regeneration expels any implant within 1D4 minutes.', 'None.', 'None.', '9+ ft (2.7+ m)', '600 to 900 lbs (270 to 407 kg)', NULL, 'Cibola, as its defenders and the soul worms'' bodyguards', NULL, NULL, 'R.C.C. with its own skills; not recommended for players (an aberrant, Anarchist individual at best)', 'Metallic, blade-covered insectoid monsters of unknown origin, once servants of the being that led the soul worms; fearless, brutal and bloodthirsty, they form the bulk of Inix''s guard. 60% carry no weapons.', 'Rifts World Book 6: South America p.136'),
('grimbor-ape-man', 'Grimbor Ape-Man', 'humanoid', 'rifts', 1, 'Any, but usually good or selfish', '{"IQ":"1D6+3","ME":"2D6","MA":"3D6+2","PS":"5D6","PP":"2D6","PE":"5D6","PB":"2D6","Spd":"1D6+1"}', 'PE+1D6', '1D6x100', NULL, NULL, NULL, 'Hit points standard (P.E. +1D6 per level). M.D.C. only from body armor; Cibolan scouts wear 120 M.D.C. armor with a 35 M.D.C. force field.', NULL, 10, '{"attacks":6,"parry":1}', 'Attacks are Hand to Hand: Expert (four at level one) plus two racial. +6 to S.D.C. damage on top of P.S. bonuses.', 'Cibolan-trained males: Hand to Hand: Expert (never Martial Arts or Assassin); W.P.s Energy Pistol, Energy Rifle and Blunt; Weapon Systems and First Aid (+5% each); Radio: Basic (+10%); tracking of humans and animals (+20%); Gobblely at 90% and Dragonese/Elven (+15%). Every grimbor: Carpentry 60%, Wilderness Survival 80%, Land Navigation 80%, plant and fruit identification 60%, animal tracking 50% (males); two related skills at levels 3, 6, 9, 12 and 15.', 'Nightvision 40 ft, good color vision, tracks by smell 60% (males), swims 20%, poor climbers.', NULL, NULL, '6 ft (1.8 m) on its knuckles, 10 to 12 ft (3.0 to 3.6 m) upright', '600 to 800 lbs (270 to 360 kg)', NULL, 'Semi-nomadic tribes in the jungle around Cibola; originally the Palladium World''s Yin-Sloth Jungles and Floenry Isles', NULL, NULL, 'R.C.C. with its own skills; males owe Cibola years of military service The class is grimbor; this row takes grimbor-ape-man because Conversion Book One''s Grimbor already holds the creature slug grimbor.', 'Gentle gorilla-like giants from the Palladium World, smarter than apes and able to use tools and guns. Inix, posing as a grimbor god, brought thousands to Cibola and spends them as cannon fodder; they are friendly with the pogtalians.', 'Rifts World Book 6: South America p.138'),
('felinoid', 'Felinoid (Jaguar Mutant)', 'mutant', 'rifts', 1, 'Any', '{"IQ":"3D6","ME":"3D6+4","MA":"3D6","PS":"4D6+4","PP":"4D6","PE":"4D6","PB":"3D6","Spd":"5D6"}', 'PE+1D6', '1D6x10', NULL, NULL, 'ME+1D4x10', 'HP: the first level''s die is in the formula; +1D6 per level. S.D.C. is the racial figure; O.C.C. and skill S.D.C. add to it. M.D.C. comes only from armor or magic. ISP: plus 1D6+1 per level of experience. Sub-strains adjust the jaguar dice by hand: lion (7%) +2D6 P.S. and Spd, -1D4 I.Q.; leopard (5%) +1D6 P.P. and Spd, -1D6 M.E.; puma (5%) +1D6 P.P. and P.E., -1D4 M.A.; tiger (3%) +2D6 P.S. and P.E., -1D6 Spd; ocelot, serval or caracal (3%) -1D6 M.E., P.S. and Spd.', NULL, 9, '{"initiative":1}', 'Horror Factor 10 for the larger strains (lion, leopard, puma, tiger). +10% to Climbing and Acrobatics when the O.C.C. gives them, and +3 ft to every leap. Attacks per melee and other combat bonuses come from the O.C.C. and hand to hand skill.', 'No R.C.C. skills; skills come from the O.C.C. Any O.C.C. except Coalition or high-tech soldiers, power armor or Glitter Boy pilots and Juicers. Over 70% of city felinoids hold civilian trades; typical adventurers are Wilderness Scouts (21%), Headhunters, Mercenaries or Special Forces (20%), Priests of the Divine Felines (8%), Mind Melters (6%) and a scattering of magic users.', 'Nightvision 200 ft (61 m); sharp hearing and smell; stronger and quicker than a human but not supernatural; retractable claws and fangs; a few cat habits such as daytime naps and purring.', 'None, except through a magic O.C.C.', 'Major psionic: eight powers from one of Sensitive, Physical or Healing, or six from any mix of the three.', '5 to 7 ft (1.5 to 2.1 m); jaguars 5 to 6 ft, the larger strains 6.5 to 7.5 ft, tigers up to 8 ft', '140 to 220 lbs (63 to 99 kg)', NULL, 'Omagua and the surrounding Amazon jungle, where they are the most numerous people', NULL, NULL, 'Takes an O.C.C.; see the class', 'Jaguar-human mutants bred by the Argentine Empire''s Achilles Project. Nearly human in temperament, they are the working backbone of Omagua and are often confused with the werejaguars. Most distrust cybernetics and favor blades.', 'Rifts World Book 6: South America p.107-109'),
('flying-tiger', 'Flying Tiger', 'mutant', 'rifts', 1, 'Any', '{"IQ":"3D6","ME":"3D6+6","MA":"3D6","PS":"4D6+4","PP":"3D6+6","PE":"3D6+4","PB":"3D6","Spd":"5D6"}', 'PEx2+1D6', '1D6x100', NULL, NULL, 'ME+2D4x10', 'HP: the first level''s die is in the formula; plus 1D6 per level. M.D.C. is the psionic force field only (10 I.S.P. to raise, lasts 4 minutes per level), plus 10 per level; the body itself is S.D.C. ISP: plus 10 per level of experience. Spd 5D6 is on the ground; flight reaches Mach One. The field (or aura) has 90 M.D.C. plus 10 per level; it is not the body, so mdc is left empty, as the class does.', NULL, 10, '{"initiative":2}', 'One extra attack per melee on top of hand to hand, +2 initiative on the ground or in the air, +1 save vs psionics, +1 save vs magic. In flight only: another +1 initiative, +2 strike and parry, +5 dodge.', 'R.C.C. skills: Basic Math +20%, Lore: Demons and Monsters +10%, Spanish +30%, Ancient Egyptian +30%, one language of choice +15%, Land Navigation +20%, Tracking: Humans and Monsters +15%, Tracking: Animals +10%, Wilderness Survival +10%, Acrobatics +10%, Prowl +15%, W.P. Energy Rifle, two W.P. of choice, Hand to Hand: Expert (to Martial Arts, or Assassin if evil, for one other skill). Four R.C.C. related skills plus one at levels 3, 7, 11 and 15; four secondary skills plus two at levels 2, 4, 8 and 12. All serve in the Omaguan military or its reserve.', 'Psychokinetic supersonic flight (Mach One, no I.S.P.), steered with squirrel-like skin membranes; nightvision 1000 ft (305 m) and hawk-sharp sight; psionic force field whose wearer strikes for M.D. while it is up.', 'None.', 'Master psionic: eight powers from Healing, Sensitive or Physical in any mix, besides the racial flight, force field and force blasts.', '6 to 8 ft (1.8 to 2.4 m)', '180 to 220 lbs (81 to 99 kg)', NULL, 'Omagua, where they form its air force', NULL, NULL, 'R.C.C. with its own skills; military', 'An accidental Achilles Project strain of psychokinetic cats, spliced with bat genes, that fly by mind power and glide on skin flaps. Tigers (60%) and jaguars (40%), they serve as Omagua''s air force in custom cat warrior armor (60 M.D.C.).', 'Rifts World Book 6: South America p.109-111'),
('flame-panther', 'Flame Panther', 'mutant', 'rifts', 1, 'Any', '{"IQ":"3D6","ME":"4D6","MA":"3D4","PS":"3D6+3","PP":"3D6+4","PE":"3D6+4","PB":"3D6","Spd":"3D6"}', 'PEx2+1D6', '1D4x100+100', NULL, NULL, 'ME+3D4x10', 'HP: the first level''s die is in the formula; plus 1D6 per level. M.D.C. is the flame aura only (10 I.S.P., one minute per level), plus 10 per level; the body itself is S.D.C. ISP: plus 10 per level of experience. The field (or aura) has 70 M.D.C. plus 10 per level; it is not the body, so mdc is left empty, as the class does.', NULL, 9, NULL, 'Horror Factor 14 while wrapped in the flame aura. +1 to strike with the flame bolt. No other racial combat bonuses are printed; attacks come from hand to hand.', 'R.C.C. skills: Basic Math +10%, Lore: Demons and Monsters +10%, Spanish +30%, Ancient Egyptian +30%, one language of choice +10%, Land Navigation +10%, Tracking: Humans and Monsters +15%, First Aid +15%, Wilderness Survival +10%, Prowl +10%, W.P. Energy Rifle, two W.P. of choice, Hand to Hand: Expert (to Martial Arts for one other skill). Four R.C.C. related skills plus one at levels 3, 7, 11 and 15; four secondary skills plus two at levels 2, 4, 8 and 12.', 'Burster-style immunity to fire and heat (M.D. plasma, napalm and magic fire do one-tenth, electricity half); puts out fires at range (4 I.S.P.); flame aura; plasma flame bolts; rocket jumps of 200 ft plus 50 ft per level (2 I.S.P. each, hard to aim, -3 to strike when rammed at a target); senses fire as a Burster.', 'None.', 'Master psionic, mostly pyrokinetic; also three powers from each of Sensitive, Healing and Physical.', '6 to 7 ft (1.8 to 2.1 m)', '300 lbs (135 kg)', NULL, 'Omagua; squads of 6 to 10 guard the city and its region', NULL, NULL, 'R.C.C. with its own skills; warriors', 'Red-brown felinoids of a pyrokinetic strain the Achilles Project never managed to repeat. The Rifts made them super-pyrokinetic; they are dedicated defenders of Omagua, feared by jungle dwellers, and serve as its firefighters too.', 'Rifts World Book 6: South America p.111-112'),
('hunter-cat', 'Hunter Cat', 'mutant', 'rifts', 1, 'Any, but lean toward selfish or evil; very few are good', '{"IQ":"3D6","ME":"3D6","MA":"2D6","PS":"5D6+12","PP":"3D6+8","PE":"4D6+6","PB":"4D6","Spd":"2D6x10"}', 'PEx5+2D6', '4D6x100', NULL, NULL, 'ME+2D6x10', 'HP: the first level''s die is in the formula; plus 2D6 per level. S.D.C. plus skill bonuses. M.D.C. is the psionic force field only (10 I.S.P., 10 minutes per level, self only), plus 10 per level; the body itself is S.D.C. ISP: plus 10 per level of experience. P.S. and P.E. are supernatural (the strength in P.P.E.-rich places). I.Q. halves if the cat goes feral. The field (or aura) has 150 M.D.C. plus 10 per level; it is not the body, so mdc is left empty, as the class does.', NULL, 12, '{"initiative":2,"strike":2,"parry":2,"dodge":2,"pull":4}', 'One extra attack per melee, +4 save vs Horror Factor, +2 save vs psionics, +2 save vs magic, +30% save vs coma and death. In a killing frenzy: initiative and the Horror Factor save triple, pull punch is lost, +10 P.S., +1 on each of strike, parry and dodge; its force field also snaps on unbidden when I.S.P. allow.', 'R.C.C. skills: Basic Math +10%, Lore: Demons and Monsters +10%, Spanish +30%, Ancient Egyptian +30%, one language of choice +10%, Land Navigation +10%, Tracking: Humans and Monsters +20%, Tracking: Animals +20%, Wilderness Survival +15%, Prowl +15%, W.P. Energy Rifle, two W.P. of choice, Hand to Hand: Martial Arts (Assassin if evil). Four R.C.C. related skills plus one at levels 3, 7, 11 and 15; four secondary skills plus two at levels 2, 4, 8 and 12.', 'Supernatural strength in P.P.E.-rich places; meditative bio-regeneration of 1D4x10 S.D.C. and 4D6 H.P. a minute, triggered automatically when knocked out; psionic force field and force blasts; retractable claws (+10% climb); prone to berserk killing frenzies that oracle cats, simvan or empaths can calm.', 'None.', 'Master psionic: 1D4+1 Physical and 1D4 Super powers besides the racial force field and blasts.', '6 to 8 ft (1.8 to 2.4 m)', '300 to 600 lbs (140 to 270 kg)', NULL, 'Omagua as its protectors; feral renegades claim a 50 mile (80 km) jungle territory', NULL, NULL, 'R.C.C. with its own skills; warriors', 'The Achilles Project''s ultimate killing machine, spliced from tiger, jaguar, gorilla and human. Most guard Omagua, but their blood lust makes some berserk murderers, feral beasts or evil warlords.', 'Rifts World Book 6: South America p.113-114'),
('oracle-cat', 'Oracle Cat', 'mutant', 'rifts', 1, 'Any, but lean toward good or selfish', '{"IQ":"3D6+8","ME":"4D6+6","MA":"3D6+6","PS":"2D6","PP":"4D6","PE":"3D6","PB":"4D6","Spd":"4D6"}', 'PE+1D6', '1D4x10', NULL, '2D6', 'ME+4D6x10', 'HP: the first level''s die is in the formula; plus 1D6 per level. S.D.C. plus skill bonuses. M.D.C. is the psionic force field only, 10 per level (10 I.S.P., one minute per level); the body itself is S.D.C. ISP: plus 10 per level of experience. The field is not the body, so mdc is left empty, as the class does.', NULL, NULL, NULL, 'No racial combat bonuses are printed; attacks come from hand to hand.', 'R.C.C. skills: Basic and Advanced Math +20%, Lore: Demons and Monsters +20%, Spanish +30%, Ancient Egyptian +30%, one language of choice +15%, Literacy +10%, Paramedic +20%, W.P. Energy Rifle, two W.P. of choice, Hand to Hand: Martial Arts (Assassin if evil). Six R.C.C. related skills plus one at levels 3, 5, 7, 11 and 15; four secondary skills plus two at levels 2, 4, 8 and 12. Divine Oracles use the Priest O.C.C. skills instead.', 'Aura of Peace: a tele-empathic wave that strips anger, hatred and fear from animals, monsters and people (standard save, +2 for berserkers and the overwhelmed); a weak psionic force field.', 'None, except Divine Oracles, who add clerical powers.', 'Master psionic. Inborn: Clairvoyance, Empathy, Presence Sense, See the Invisible, Mind Block, Sense Magic, Telepathy, Empathic Transmission. From level 2, two Sensitive, Physical or Healing powers or one Super each level; after level 5, two lesser plus one Super.', '4 to 5 ft (1.2 to 1.5 m)', '50 to 100 lbs (22.5 to 45 kg)', NULL, 'Omagua', 'Hunter cats, whom they calm', NULL, 'R.C.C. with its own skills; leaders', 'Descendants of Zee and the ZB-23 batch: big-headed, toy-like felines whose cute looks hide great psionic power and glimpses of the future. They are Omagua''s most respected race, serving as leaders, advisors, healers and judges; a few become Divine Oracles.', 'Rifts World Book 6: South America p.114-115'),
('sekhmet', 'Sekhmet', 'humanoid', 'rifts', 1, 'Any; most are good or selfish', '{"IQ":"3D6","ME":"3D6","MA":"3D6","PS":"4D6+10","PP":"3D6+4","PE":"4D6+4","PB":"3D6","Spd":"4D6"}', NULL, NULL, '3D6x10', 'PE+2D6x10', 'ME+1D4x10', 'MDC: plus 2D6 per level of experience; a mega-damage being with no H.P. or S.D.C. printed. PPE: plus 2D6 per level. ISP: plus 1D6 per level. P.S. and P.E. are supernatural.', NULL, 12, '{"initiative":1,"strike":2,"parry":1,"dodge":1,"pull":1,"roll":1}', '+1 save vs magic and psionics, +5 save vs Horror Factor. No attacks per melee figure is printed; attacks come from hand to hand.', 'R.C.C. skills: Basic Math +15%, Ancient Egyptian +20%, Dragonese/Elf +15%, one language of choice +15%, Track Animals +20%, Track Humans/Monsters +15%, Wilderness Survival +20%, Detect Ambush +10%, Swim +10%, two W.P. of choice, Hand to Hand: Expert (to Martial Arts for one other skill). Five R.C.C. related skills plus one at levels 3, 5, 7, 11 and 15; five secondary skills plus two at levels 3, 8 and 12.', 'Supernatural strength and endurance; nightvision 200 ft (61 m) and keen sight; regenerates 1D6x10 M.D.C. an hour.', 'Learns spells by mystic insight: four from levels 1-3 at first level, then one more per level, never above the character''s own level.', 'Minor psionic: four powers from Healing or Physical.', '6 to 7 ft (1.8 to 2.1 m)', '300 to 450 lbs (135 to 203 kg)', NULL, 'Across the Megaverse in semi-nomadic war bands of 12 to 100; over 50,000 live in Omagua', 'Feline gods such as Simba, the Pantheons of Light, and the werebeasts and felinoids of Omagua', 'The Splugorth, vampires, demons and devils, gargoyles, True Atlanteans, and the Ramen and Tautons', 'R.C.C. with its own skills; warriors', 'Lion-headed humanoid hunters and warriors, named for the Egyptian goddess said to have made them, who serve feline gods. They travel in war bands split into prides and prove themselves through harsh rites of passage; many wear enchanted plate (100 M.D.C.).', 'Rifts World Book 6: South America p.116-117'),
('werejaguar', 'Werejaguar / Werepanther', 'monster', 'rifts', 1, 'Usually anarchist or any evil, occasionally unprincipled', '{"IQ":"2D6+2","ME":"3D6","MA":"4D6","PS":"4D6 min 16","PP":"4D6 min 16","PE":"4D6","PB":"4D6","Spd":"6D6"}', '6D6+10', NULL, NULL, '2D4x10+10', '5D6', 'Hit Points are special: like a vampire it shrugs off most weapons, M.D. energy, explosives, bullets, fire, wood, steel and poison included; magic, psionics and silver (double damage) hurt it, and big M.D. blasts can knock it down or stun it (the vampire Knock Down table). Hit points grow with level (no die printed). Bio-regenerates 2D6 H.P. an hour. Average level 1D4; uses the Psi-Stalker experience table. The werepanther shares these stats.', NULL, 12, '{"attacks":5,"initiative":1,"strike":2,"parry":2,"dodge":2}', 'Five attacks per melee in half-beast or animal shape, two in human shape; Horror Factor 12 in half-beast shape only. +6 save vs Horror Factor, +2 save vs psionics, +2 save vs magic. Wolfbane and garlic hold it at bay; crosses, sunlight and running water do not.', 'Spanish 98%, Land Navigation 90%; natural Prowl 80%, Swim 60%, Climb 90/80%, Acrobatics 80%, Track by Smell 60%. Seven secondary skills at level one plus two at levels 3, 6, 9, 11 and 14, from Domestic, Espionage, Basic Math, Technical (language, lore, photography), any W.P., Wilderness (+20%) and a few pilot skills.', 'Shape-changes at will, day or night, among human, jaguar and half-jaguar humanoid (one melee round, no limit); talks in animal form; nightvision 300 ft (91.5 m); bio-regeneration; nearly invulnerable except to magic, psionics and silver. Its S.D.C. claws and bite do full damage to vampires and other werebeasts.', 'Casts Tongues, Chameleon, Astral Projection, Repel Animals, Heal Wounds, Metamorphosis: Animal and Metamorphosis: Human from its own P.P.E.', 'Sixth Sense, See the Invisible, Mind Block.', '6 to 7 ft tall in human and half-beast form; 5 to 6 ft long as a jaguar', '200 to 300 lbs (90 to 136 kg)', NULL, 'Jungles of Central and South America, thickest around Omagua and the Yucatan; small tribes and villages of a few dozen to about 100', 'The god Yaguar-Ogui; the felinoid races of Omagua, though they feud with the hunter cats', 'Vampires, instinctively', 'R.C.C.; secondary skills only', 'The Jaguar People, werebeasts who worship Yaguar-Ogui; thousands, with their werepanther cousins, moved to Omagua and joined its army. They avoid humans unless defending themselves, hunt animals and supernatural beings, and often release prey after a cat-and-mouse chase.', 'Rifts World Book 6: South America p.117-118');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('enumu', 'Enumu', NULL, 'Lord of Drought', 'rifts', 'Demon Lord', 'Demon Lord, equal to a 15th level warlock', 15, 'Miscreant', NULL, NULL, NULL, '{"IQ":17,"ME":20,"MA":18,"PS":27,"PP":19,"PE":25,"PB":6,"Spd":43}', NULL, NULL, 1800, 4000, NULL, NULL, 16, '{"attacks":7,"initiative":2,"strike":6,"parry":6,"dodge":7,"roll":4,"pull":4}', 'Attacks: 7 hand to hand or 3 spells. Damage bonus +12. +10 to save vs poison, +6 vs magic, +5 vs psionics, +10 vs Horror Factor. Level is his warlock equivalent; he is a Mega-Damage being.', '[{"name":"Mathematics: Advanced","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Astronomy","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Wilderness Survival","pct":98},{"name":"Anthropology","pct":98},{"name":"Land Navigation","pct":98},{"name":"Language: Demongogian","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: American","pct":98},{"name":"Language: Euro","pct":98},{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: Creole","pct":98},{"name":"Literacy: Demongogian","pct":98},{"name":"Literacy: Spanish","pct":98},{"name":"Literacy: American","pct":98},{"name":"Literacy: Euro","pct":98},{"name":"Literacy: Dragonese/Elf","pct":98},{"name":"Literacy: Creole","pct":98}]', 'The book lists wilderness survival twice in one sentence; it is stored once. Literate and fluent in each language, all at 98%.', 'Nightvision 4000 feet (1220 m), sees the invisible and turns invisible at will. Bio-regenerates 1D4x10 M.D.C. per minute (four melee rounds). Weather magic cannot touch him and electricity of any kind does him no harm; other energy attacks do only a quarter damage. Teleport 65%, dimensional teleport 72% (known dimensions only, Hades and Dyval among them). Weather Control: commands rain, wind and climate across a 1000 mile (1600 km) radius, disturbing weather far beyond it. Negate Weather Magic: blocks ordinary weather spells within 100 miles (160 km); only a very powerful mage, a warlock of 15th level or more, or a weather deity''s priest can overrule him, and weather or fertility gods cancel him easily. Vulnerable: most magic (rune weapons, circles, wards, staves, wands) and kinetic force (missiles, explosives, rail guns, M.D. punches and kicks) do full damage.', 'Knows every air, water and fire elemental spell, as a 15th level warlock.', 'None.', NULL, NULL, 'None; he depends on his natural powers alone.', NULL, 'Menacing and cruel, with a voice like distant thunder; treats mortals as livestock to torment or kill as he likes. Secretly fears dragons, stronger monsters, other demon lords and gods, keeps up a threatening front before them, and will run if a fight turns against him.', 'Haktla, the vampire intelligence ruling the Vampire Kingdom of the northern Andes, who worships him beside itself.', 'The Republic of Colombia; the Voodoo priests and deities who have thwarted his droughts there.', 'A semi-elemental demon who has posed as a rain and fertility god on many worlds, extorting sacrifices with threats of drought until he is driven out. Allied with Haktla, he keeps rain over the vampire kingdom confined to daylight and turns storms and mud slides on Colombian invaders. A top-heavy, short-legged humanoid with scaly leathery hide, a huge mouth of needle teeth, glowing eyes and six black-clawed fingers per hand.', 'Rifts World Book 6: South America p.39-40'),
('hak-talon', 'Hak-Talon', 'Edgardo Amendariz', 'Master Vampire; first among the master vampires of Haktla''s kingdom', 'rifts', 'Master Vampire', '11th level master vampire', 11, 'Diabolic', NULL, NULL, NULL, '{"IQ":25,"ME":22,"MA":28,"PS":33,"PP":27,"PE":19,"PB":23,"Spd":30}', 160, NULL, NULL, 40, 180, NULL, 14, '{"attacks":6,"initiative":3,"strike":6,"parry":6,"dodge":6}', 'Hit Points are vampire Hit Points. Attacks: 6 hand to hand, or 2 psionic with 2 hand to hand. Damage bonus +18 (S.D.C.). Saves: magic +2, psionics +4, +9 vs Horror Factor. Immune to all mind control and to psionic and magic sleep and paralysis. Combat skill: Supernatural.', '[{"name":"Wilderness Survival","pct":98},{"name":"Track Animals","pct":98},{"name":"Hunting","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: Quechua","pct":98},{"name":"Language: Demongogian","pct":98}]', 'Printed as "demon lore". W.P.s: Sword, Blunt, Energy Rifle, Heavy.', 'Every master vampire power (per Rifts Vampire Kingdoms): commands lesser vampires, turns into a wolf, a vampire bat or mist, summons vermin, cannot be hurt by ordinary weapons, heals 2D6 Hit Points each melee, sees in the dark to 1600 feet (488 m), scents blood a mile (1.6 km) off, needs no air, and knows other vampires on sight.', 'None.', 'Control other vampires, death trance, alter aura, empathy, mind block, hypnotic suggestion, presence sense, sense evil, deaden pain, induce sleep, super-hypnotic suggestion.', NULL, NULL, 'Captured Colombian arms, rocket rifles and heavy weapons among them. No armor, but a captured Splugorth talisman raises an Armor of Ithan field (100 M.D.C.) three times a day.', NULL, 'What is left of the shepherd is his worst: selfish, petty, vain and greedy for power. Plays the part of a person only to fool mortals; among his slaves he acts the god, punishing any slight and keeping them off balance with mind games.', 'Haktla, the vampire intelligence he serves; the kingdom''s vampires, demons and Brodkil.', 'The Republic of Colombia.', 'An Andean shepherd, bullied as a youth, who accepted a vampire intelligence''s offer in his dreams, slaughtered his village and helped bring Haktla to Earth. Now ambitious for more, he quietly pays agents to hunt for a ritual that might make him an intelligence himself. A short, pale man of Indian features, dressed in bright ponchos and headgear, with a frightening charisma.', 'Rifts World Book 6: South America p.40-41'),
('king-kryang', 'King Kryang', NULL, 'Pirate king of Kryang''s Land', 'rifts', 'Rathos the Rumbler', '10th level warlord', 10, 'Diabolic', NULL, '8 feet (2.4 m)', NULL, '{"IQ":14,"ME":10,"MA":12,"PS":44,"PP":20,"PE":26,"PB":3,"Spd":50}', NULL, NULL, 400, 200, NULL, NULL, 15, '{"attacks":6,"initiative":2,"strike":5,"parry":5,"dodge":5,"roll":3,"pull":3}', 'Attacks: 6 hand to hand or 2 magic. Damage bonus +29 (S.D.C.). +7 to save vs magic, +10 vs earth warlock magic, +8 vs poison, +5 vs Horror Factor. Combat skill: Supernatural. No damage table is printed for him.', '[{"name":"Land Navigation","pct":86},{"name":"Prowl","pct":80},{"name":"Climbing","pct":90},{"name":"Swim","pct":98},{"name":"Tracking","pct":80},{"name":"Language: Demongogian","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Language: Dragonese","pct":65},{"name":"Language: Elemental","pct":65},{"name":"Language: Spanish","pct":65}]', 'W.P.s: Blunt, Chain, Energy Rifle, Heavy.', 'Nightvision 400 feet (122 m); sees the invisible; ordinary fire cannot harm him and magic fire or plasma does half damage. Heals 6D6 M.D.C. every melee round and regrows a severed limb within a week.', 'Innate powers: climb, thunder clap, breathe without air, fool''s gold, magic net, repel animals, spoil water/food. Elemental spells: identify minerals, identify plants, rock to mud, crumble stone, rot wood, wither plants, wall of clay, earth rumble.', 'None.', NULL, NULL, 'Prefers Kittani arms: K-4 laser pulse rifle, KEP-Special energy pump pistol, K-E4 plasma ejector; also many neural maces, vibro-swords and other M.D. melee weapons. His prize is a Crystal Fire Rod (Rifts Atlantis) won in the Splynn Arena. Enchanted plate armor, 120 M.D.C.', NULL, 'A loud, arrogant, bragging warlord who amuses himself with savage feasts (sometimes eating captives), torture and humiliation, and cares little even for his own followers. Nonetheless a seasoned fighter and master tactician who has made himself a competent sailor since arriving.', 'His band of Ram-Rats and pirates; regards himself as a friend of Atlantis, where Lord Splynncryth tolerates him as a minor amusement.', 'The Republic of Colombia, whose navy twice attacked his harbor and badly wounded him; he has sworn vengeance.', 'A Rathos mercenary chief (race per Rifts Dimension Book One: Wormwood) swept to a South American island by a battlefield Rift, who crushed the local pirates and has ruled them for ten years, raiding coasts from Colombia to Africa. He once beat a Splugorth Conservator in the Splynn Arena. A grey, hugely muscled giant with yellow blotches, spiny growths and three taloned fingers.', 'Rifts World Book 6: South America p.44-45'),
('melastirth', 'Melastirth', NULL, 'Dragon Overlord of Lagarto', 'rifts', 'Great Horned Dragon', '20th level dragon; equal to a 10th level spell caster and a 14th level psychic', 20, 'Diabolic', '1500 years', '30 feet (9.1 m) tall and 70 feet (21.3 m) long as a dragon; 10 feet (3.0 m) in his lizard man shape', NULL, '{"IQ":28,"ME":20,"MA":27,"PS":49,"PP":17,"PE":24,"PB":23,"Spd":70}', NULL, NULL, 7500, 1000, 120, NULL, 14, '{"attacks":8,"initiative":4,"strike":4,"parry":5,"dodge":5,"roll":4,"pull":4}', 'Spd is running; flying Spd 130. Attacks: 8 physical or psionic; or 4 fire breaths with 4 physical or psionic; or 3 spells. Damage bonus +34 (S.D.C.). +9 to save vs poison, +9 vs magic, +7 vs psionics, +7 vs Horror Factor. Combat skill: Natural. Honest only with those he counts as peers (dragons, gods, major demons, other greater beings); lies to and cheats everyone else.', '[{"name":"Mathematics: Basic","pct":98},{"name":"Mathematics: Advanced","pct":98},{"name":"Literacy: Dragonese/Elven","pct":98},{"name":"Literacy: Spanish","pct":98},{"name":"Literacy: Creole","pct":98},{"name":"Literacy: American","pct":98},{"name":"Literacy: Euro","pct":98},{"name":"Literacy: Kydian","pct":98},{"name":"Literacy: Kittani","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Lore: Faerie","pct":90},{"name":"Detect Ambush","pct":98},{"name":"Detect Concealment","pct":98},{"name":"Wilderness Survival","pct":98}]', 'The book also lists "monster lore 98%" separately from demon and monster lore; stored once. W.P.s: Sword, Energy Pistol.', 'Nightvision 100 feet (30.5 m) and sight in total darkness; sees the invisible and can vanish at will. Heals 1D4x10 M.D.C. each minute. Half damage from all fire, M.D. fire and plasma included. Teleport self 92%, dimensional teleport 52%. Metamorphosis at will for as long as he likes, favoring a giant lizard man shape. Breathes fire (no damage printed in his entry).', 'All spell magic levels 1-15.', 'Every sensitive, physical and healing power; also bio-manipulation and psi-sword.', NULL, NULL, 'Assorted Kittani and Splugorth weapons and an Impaler rune sword (Rifts Atlantis). Never wears armor.', NULL, 'A gifted manipulator, orator and politician held back by contempt for every non-reptile and by visions of cosmic destiny. He underrates humans, blames each setback on the treachery of lesser races, and is genuinely insane, yet so far his madness has served him.', 'Styphathal, the dragon-god of Dragcona, whom he reveres and whose trusted lieutenant he is (Styphathal privately humors and would discard him); Stleet; the Cult of Dragonwright and the Minions of Splugorth in Lagarto.', 'Every non-dragon race; the lizard man resistance; Colombia, El Dorado''s cities and the other nations Lagarto means to conquer.', 'A zealot of the evil Dragonwright faith who preaches that dragons must enslave every other race, and who seized the lizard men of the Amazon as the first step of a 50,000 year crusade. As a dragon he is a golden-orange horned beast with a great spiny crest.', 'Rifts World Book 6: South America p.75-77'),
('stleet', 'Stleet', NULL, 'High King of Lagarto, Defender of the Scaled Ones, Paladin of Dragonwright', 'rifts', 'Lizard man bio-borg', '8th level warrior', 8, 'Miscreant', NULL, '6 feet (1.8 m)', NULL, '{"IQ":14,"ME":12,"MA":17,"PS":30,"PP":21,"PE":21,"PB":22,"Spd":44}', NULL, NULL, 200, 3, NULL, NULL, 14, '{"attacks":4,"initiative":1,"strike":5,"parry":6,"dodge":6,"roll":2,"pull":2}', 'Horror Factor applies only in an attack frenzy. Attacks: 4, plus one fire breath. Underwater: +6 strike, +7 parry, +8 dodge. +15 to S.D.C. damage. +6 to save vs poison, +3 vs magic. Supernatural strength and endurance. Combat training: H2H Expert, plus basic power armor combat.', '[{"name":"Fishing","pct":98},{"name":"Dance","pct":75},{"name":"Play Musical Instrument","pct":80},{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: Creole","pct":98},{"name":"Mathematics: Basic","pct":90},{"name":"Climbing","pct":90},{"name":"Pilot: Sail Boat","pct":98},{"name":"Pilot: Motor Boat","pct":98},{"name":"Boat Building","pct":80},{"name":"Track Animals","pct":65},{"name":"Preserve Food","pct":70},{"name":"Land Navigation","pct":73},{"name":"Wilderness Survival","pct":80},{"name":"Swim","pct":90}]', 'Swim 90% is a racial natural ability. W.P.s: Sword, Blunt, Energy Pistol, Energy Rifle. Pilots a Raptor power armor.', 'Breathes underwater; polarized vision; swims 90%. Bio-Wizard dragon''s breath implants give a flame breath once per melee as an extra attack. Supernatural strength and endurance from the same treatment.', 'None.', 'None.', NULL, NULL, 'Likes vibro-swords, spears and other archaic weapons. A lesser rune bastard sword (6D6 M.D., evil alignment, I.Q. 13, standard rune sword powers). A Kittani KEP-Special energy pump pistol (5D6 M.D.) as sidearm. A Kittani Raptor power armor. Kittani explorer armor, gilded and polished, 85 M.D.C.', NULL, 'A thorough scoundrel who will betray anyone for gain and lies constantly but carefully. Loyal to neither Melastirth nor the cult; ready to claim he was a brainwashed victim if the lizard men revolt, and to flee to pirates or Cibola if that fails.', 'Melastirth and the Cult of Dragonwright, for as long as it pays.', 'The lizard man rebels; over 30 would-be assassins, most of them his own servants and associates; agents of Cibola, who secretly staged the bombing that nearly killed him.', 'A lizard man village warrior turned pirate captive and bodyguard, who murdered his master, stole his treasure and remade himself as a hero. A convert to Dragonwright for gain, he staged the killing of the elder chief at Melastirth''s command and was made High King, then rebuilt in Atlantean bio-wizard vats with supernatural strength and fire breath. A tall, heavily muscled lizard man with yellow eyes and a few scars.', 'Rifts World Book 6: South America p.77-78'),
('bast', 'Bast', NULL, 'Egyptian Cat Goddess; one of the Divine Felines of Omagua', 'rifts', 'Goddess', '15th level ley line walker; 10th level stone master and mind melter', 15, 'Unprincipled', NULL, NULL, NULL, '{"IQ":21,"ME":18,"MA":23,"PS":23,"PP":26,"PE":20,"PB":22,"Spd":66}', NULL, NULL, 9000, 4000, 1000, NULL, 15, '{"attacks":5,"initiative":2,"strike":8,"parry":11,"dodge":11,"roll":2,"pull":2}', 'M.D.C. is her figure in most places; inside the Great Palace at Omagua it is 45,000 (outside the city she has one-fifth of that). Attacks: 5 hand to hand or 2 spells. Bonuses are printed as totals. +5 to save vs poison, +5 vs magic, +7 vs psionics, +10 vs Horror Factor. Supernatural strength and endurance. Combat skill: Hand to Hand: Expert.', '[{"name":"Wilderness Survival","pct":98},{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: Ancient Egyptian","pct":98},{"name":"Language: Creole","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: American","pct":98},{"name":"Language: Euro","pct":98},{"name":"Language: Demongogian","pct":98},{"name":"Language: Portuguese","pct":98},{"name":"Literacy: Dragonese/Elf","pct":98},{"name":"Literacy: Ancient Egyptian","pct":98},{"name":"Literacy: Creole","pct":98},{"name":"Literacy: Spanish","pct":98},{"name":"Literacy: American","pct":98},{"name":"Literacy: Euro","pct":98},{"name":"Literacy: Demongogian","pct":98},{"name":"Literacy: Portuguese","pct":98}]', 'Every wilderness and domestic skill at 98%. W.P.s: Sword, Blunt, Energy Rifle.', 'Nightvision 1000 feet (305 m); sees the invisible and can vanish at will. Teleport 89%, dimensional teleport 80%. Shifts into any feline shape at will with unchanged stats, favoring a cat-headed woman, a furry cat humanoid like a werejaguar''s middle form, and a giant cat. Half damage from cold and heat. Bio-regenerates 4D6x10 M.D.C. per minute (four melee rounds).', 'Every spell of levels 1-15, cast at 15th level; every stone magic spell, at 12th level.', 'Every healing, sensitive and physical power, at 10th level.', NULL, NULL, 'Enchanted scale armor, 1,000 M.D.C. The Cat''s Gauntlet (greatest rune weapon): a silver clawed glove, I.Q. 10, telepathically linked to her, indestructible, Unprincipled (an evil being touching it takes 4D6 burns). Three times a day each it casts blinding flash, globe of daylight, cloud of smoke, wall of flame, circle of flame, fire bolt, fire ball, ignite fire, fuel flame and impervious to fire as a 12th level warlock. Its claws do 1D6x10 M.D. (double to alien intelligences); three chained knuckle spikes shoot out 100 feet (30.5 m), each doing 3D6 M.D. and snagging the target to be hauled in (opposed D20 plus P.S. bonus). She gives a few favored followers lesser copies with damage and spell levels halved.', NULL, 'Wholly a cat: regal one moment and idle the next, graceful and then playfully cruel. Generous with friends, and anyone who offends her is shredded by her tongue or her claws. Easily bored and restless, she slips away on adventures and patrols against her fellow gods'' wishes.', 'Yaguar-Ogui and Simba, her partners in ruling Omagua; her personal army of Ramen warriors.', 'The forces of evil; she broke with Ra and the Gods of Light but never joined the Pantheon of Taut.', 'Egypt''s goddess of light and revelry, long tied to Ra''s pantheon, who walked out on him when he refused to hand her the Ramen and joined Yaguar-Ogui in founding Omagua, whose Egyptian flavor is her doing. Usually appears as a lovely cat-headed woman in gold.', 'Rifts World Book 6: South America p.119-120'),
('yaguar-ogui', 'Yaguar-Ogui', NULL, 'the Jaguar, South American Feline God; also called Chacha-Puma and El Jaguar', 'rifts', 'God-level Werejaguar', '15th level warrior and mystic', 15, 'Unprincipled with anarchistic leanings (formerly Scrupulous)', NULL, '12 feet (3.7 m)', NULL, '{"IQ":21,"ME":19,"MA":20,"PS":32,"PP":27,"PE":23,"PB":20,"Spd":66}', 3000, NULL, NULL, 2000, 800, NULL, 17, '{"attacks":6,"initiative":3,"strike":8,"parry":11,"dodge":11,"roll":3,"pull":3}', 'No M.D.C.: special limited invulnerability instead. Hit Points are his figure in most places; within the Omagua Great Palace they rise to 15,000. Attacks: 6 hand to hand or psionic, or 3 spells. +10 to save vs poison, +10 vs magic, +7 vs psionics, +10 vs Horror Factor. Combat skill: Hand to Hand: Martial Arts.', '[{"name":"Language: Spanish","pct":98},{"name":"Language: Creole","pct":98},{"name":"Language: American","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Language: Demongogian","pct":98},{"name":"Language: Greek","pct":98},{"name":"Language: Ancient Egyptian","pct":98},{"name":"Language: Euro","pct":98},{"name":"Language: Dragonese/Elf","pct":98},{"name":"Literacy: Spanish","pct":98},{"name":"Literacy: Creole","pct":98},{"name":"Literacy: American","pct":98},{"name":"Literacy: Gobblely","pct":98},{"name":"Literacy: Demongogian","pct":98},{"name":"Literacy: Greek","pct":98},{"name":"Literacy: Ancient Egyptian","pct":98},{"name":"Literacy: Euro","pct":98},{"name":"Literacy: Dragonese/Elf","pct":98}]', 'Fluent and literate in each, printed at 98% after the last name only. W.P.: Sword.', 'Nightvision 200 feet (61 m). Takes human, half-beast or jaguar shape at will. Sight and hearing equal to advanced cybernetic senses. Teleport 88%, dimensional teleport 65%. A super-werebeast: immune to nearly every weapon, M.D. energy weapons, explosives, bullets, fire, wood and poison/drugs included, but ordinary silver, magic and the hand to hand attacks of supernatural beings do full damage. Regenerates 1D4x10 per melee round (printed as M.D.C., though his pool is Hit Points).', 'All spell magic levels 1-10, plus banishment, mystic portal, wards, anti-magic cloud, remove curse, summon and control animals, amulet, calm storms, summon entity, time hole, protection circle: superior, summon storm, summon lesser being, sanctum, talisman, close rift, restoration and dimensional portal.', 'Every mystic O.C.C. ability, and every sensitive and physical power, at 15th level.', NULL, NULL, 'Seldom carries any, relying on claws and magic. Magical robes, 500 M.D.C.', NULL, 'Once both a wild totem and a wise patron of cities: in a hunt or battle he turns bestial, strikes from ambush and spares no one, and he fights politics the same way, delighting in surprise. In governing the city he is endlessly patient.', 'Bast and Simba; the werejaguars and the felinoid peoples of Omagua; the Indian tribes who still call on him.', 'Vampires and other undead, the Ellal among them; the Inca gods he has never forgiven; he distrusts Atlanteans and so Manoa; Cibola, the Splugorth, demons and Lagarto, who prey on his worshippers.', 'The ancient jaguar god of hunters and warriors, maker of the werejaguars, whose worship the Inca gods pushed into the jungle. Embittered, he withdrew to a pocket-dimension city of werejaguars before gathering Bast and Simba to found Omagua, and now plans to aid the human tribes still loyal to him. A towering werejaguar in leopard-spotted robes and a gold crown.', 'Rifts World Book 6: South America p.120-121'),
('simba', 'Simba', NULL, 'African Lion God; one of the Divine Felines of Omagua', 'rifts', 'God', '16th level warrior and magician', 16, 'Anarchist', NULL, '6 to 24 feet (1.8 to 7.3 m), at will', NULL, '{"IQ":18,"ME":17,"MA":19,"PS":52,"PP":22,"PE":30,"PB":17,"Spd":88}', NULL, NULL, 8500, 2000, NULL, NULL, 16, '{"attacks":8,"initiative":4,"strike":10,"parry":12,"dodge":12,"roll":6,"pull":6}', 'M.D.C. is his figure in most places; within the Omagua Great Palace it rises to 42,500. Attacks: 8 hand to hand or 2 spells. +10 to save vs poison, +8 vs magic, +8 vs psionics, +10 vs Horror Factor. Combat skill: Hand to Hand: Martial Arts.', NULL, 'No skills printed. Knows every W.P.', 'Nightvision 200 feet (61 m); sees the invisible; half damage from heat and fire. Teleport 90%, dimensional teleport 82%. Bio-regenerates 1D4x100 M.D.C. per minute (four melee rounds). Can become a giant lion, and can change his size anywhere from 6 feet (1.8 m) up to 24 feet (7.3 m).', 'All spells levels 1-7, plus luck curse, metamorphosis: human, minor curse, negate magic, oracle, curse: phobia, mute, speed of the snail, water to wine, banishment, metamorphosis: superior, mystic portal, anti-magic cloud, remove curse, amulet, metamorphosis: mist, time hole, close rift, impenetrable wall of force.', 'None.', NULL, NULL, 'No armor; trusts his own hide. Simba''s War Club: greatest rune weapon; its head is a clenched, clawed fist: I.Q. 13, telepathically linked to him, indestructible, blue, Anarchist (a good or evil being touching it takes 4D6 burns). Three times a day each it casts invulnerability, levitation, summon rain and calm storms as an 8th level sorcerer. Strikes for 2D4x10 M.D.; on his mental command the fist opens to seize a target and tear or crush it.', NULL, 'Rules by intimidation, punctuating speech with growls and roars that can break glass. Treats everything as a contest he must win, and values warriors far above mages, scholars and psychics.', 'Yaguar-Ogui and Bast, though both dislike his use of Omagua''s warriors in wars on other worlds.', 'He covets Manoa and Cibola, and Yaguar-Ogui and a few others have begun to suspect it; the aggressive gods and alien intelligences that stripped him of worshippers on many worlds.', 'A lion-headed warrior god, golden-furred, the last of a mostly vanished animal pantheon and a minor spirit in Africa. Down on his luck, he accepted Yaguar-Ogui''s second invitation and helped bring Omagua to Earth, but sees the city only as a stepping stone to restoring his cult in Africa and to wider conquest.', 'Rifts World Book 6: South America p.121-123'),
('inix', 'Inix', 'Inixclajk', 'Alien Intelligence; ruler of the city of Cibola', 'rifts', 'Soul Worm (alien intelligence)', '10th level Soul Worm R.C.C.', 10, 'Miscreant', NULL, NULL, NULL, '{"IQ":29,"ME":23,"MA":25,"PS":38,"PP":24,"PE":28,"PB":2,"Spd":30}', NULL, NULL, 14000, 2000, 1200, NULL, 15, '{"attacks":6,"initiative":1,"strike":7,"parry":6,"dodge":6,"roll":-1,"pull":2,"damage":23}', 'Combat is Supernatural. Per melee: 6 attacks (hand to hand or psionic), or 2 when casting magic. Roll with impact is printed as -1. Damage is +23 to S.D.C. damage. +7 to save vs poison, +8 vs magic, +5 vs psionics, +10 vs Horror Factor. Mind control and possession cannot affect him. No Hit Points or S.D.C. printed for him.', '[{"name":"Literacy: American","pct":98},{"name":"Literacy: Spanish","pct":98},{"name":"Literacy: Euro","pct":98},{"name":"Literacy: Creole","pct":98},{"name":"Literacy: Atlantean","pct":98},{"name":"Literacy: Dragonese/Elf","pct":98},{"name":"Literacy: Demongogian","pct":98},{"name":"Literacy: Galactic Trade Tongue I","pct":98},{"name":"Literacy: Kydian","pct":98},{"name":"Literacy: Gobblely","pct":98},{"name":"Intelligence","pct":98},{"name":"Swimming","pct":98},{"name":"Detect Ambush","pct":98},{"name":"Detect Concealment","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Lore: D-Bee","pct":98},{"name":"Lore: Splugorth","pct":98},{"name":"Lore: Faerie","pct":98},{"name":"Anthropology","pct":98},{"name":"Archaeology","pct":98}]', 'Magically knows all languages, so no spoken-language percentages are printed. No W.P.s; he relies on his powers.', 'The entry says he has the abilities of every soul worm; the species entry that follows (p.129) gives nightvision to 500 feet (152 m), sees the invisible, invisibility at will, invulnerability to fire including M.D. fire and plasma, regeneration of 2D6x10 M.D.C. each melee round, self-teleport as far as 100 miles (160 km), dimensional teleport (72%) to known dimensions, and Soul Draining, which strips a helpless victim of P.P.E., I.S.P. and finally M.E. and memories. Twelve tentacles ring his single huge eye.', 'All spell magic levels 1-5, plus Call Lightning, Compulsion, Time Slip, Life Drain, Locate, Minor Curse, Negate Magic, Control/Enslave Entity and Metamorphosis (Superior).', 'All Sensitive powers plus Empathic Transmission, Hypnotic Suggestion and Mind Wipe; powers work as an 8th level Mind Melter.', NULL, NULL, 'None; relies on his powers and never wears armor.', NULL, 'Greedy, devious and cunning in a very human way; wants wealth and power but is too cautious to launch wars of conquest, so he builds Cibola into a great dimensional trading post instead. Bullies lesser mortals and flatters and charms his equals, often taking a human or godlike shape by magic to impress them.', 'His four advisors - Malkhom, Iridna, Rendell and Kastor - plus the Gatherers and the city''s armies of Pincer Warriors and hired Pogtalian Dragon Slayers.', NULL, 'A giant fleshy worm with one great eye ringed by a dozen long tentacles, which he gestures with like hands. The soul worm lord of Cibola; by Metamorphosis he often appears as a grey-bearded, sharp-featured middle-aged man or as a 12 foot (3.7 m) godlike humanoid.', 'Rifts World Book 6: South America p.127-128'),
('malkhom', 'Malkhom', NULL, 'Cibola''s Head of Security; chief of Inix'' Intelligence Network', 'rifts', 'Temporal Raider', '14th level temporal raider', 14, 'Aberrant', NULL, NULL, NULL, '{"IQ":19,"ME":21,"MA":12,"PS":20,"PP":19,"PE":17,"PB":9,"Spd":20}', NULL, NULL, 310, 390, 49, NULL, 13, '{"attacks":6,"initiative":6,"strike":7,"parry":9,"dodge":9,"roll":5,"pull":5}', 'Per melee: 6 hand to hand or psionic attacks, 12 light or 6 heavy energy blasts, or 2 magic attacks. +8 to strike with energy blasts. +4 to save vs magic, +6 vs psionics, +10 vs Horror Factor.', '[{"name":"Land Navigation","pct":98},{"name":"Wilderness Survival","pct":98},{"name":"Pilot: Hovercraft","pct":98},{"name":"Pilot: Jet Aircraft","pct":98},{"name":"Horsemanship","pct":98},{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: Demongogian","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: Creole","pct":98},{"name":"Language: American","pct":98}]', 'W.P.s: Sword, Energy Pistol, Energy Rifle, Knife.', 'Senses dimensional anomalies and can phase along ley lines; draws sustenance from living creatures'' life force; poisons, toxins, drugs, gases, fire and heat cannot harm him; needs no air; energy does him half damage. Bio-regenerates 4D6 each melee round at the cost of one attack. Fires energy blasts from hands, eyes or mouth.', 'All temporal magic spells and all spells of levels 1-2, plus summoning magic, Protection Circle: Simple and Superior, Eyes of Thoth, Shadow Meld, Time Slip, Negate Magic, Mystic Portal, Close Rift and Dimensional Portal.', 'Alter Aura, Death Trance, Levitation, Mind Block, Empathy, Telepathy.', NULL, NULL, 'An NE-4P Plasma Cartridge pistol as his sidearm; seldom wears armor. Dresses in solid black capes or hooded cloaks.', NULL, 'Icily calm under any pressure, with a stare that suggests he already knows the truth. Ruthless and calculating yet mindful of consequences; he will use kindness or bribery as readily as threats, torture or murder, whichever works best. Never shows emotion.', 'Inix, who trusts him above his other advisors; Iridna respects his mind. Spies in Cibola and its neighbours.', NULL, 'An evil but often honorable temporal raider who runs Cibola''s intelligence and security, often away on other worlds for espionage or assassination. Widely believed to hold damaging evidence on the other advisors and most officials. A grey, hairless humanoid with a metallic, mask-like face and plate growths on arms, neck and chest.', 'Rifts World Book 6: South America p.129-130'),
('iridna', 'Iridna', NULL, 'Inix''s War Chief', 'rifts', 'Godling', '12th level godling', 12, 'Diabolic', NULL, NULL, NULL, '{"IQ":17,"ME":20,"MA":22,"PS":43,"PP":24,"PE":28,"PB":23,"Spd":34}', NULL, NULL, 641, 30, NULL, NULL, 10, '{"attacks":7,"initiative":4,"strike":10,"parry":9,"dodge":9,"roll":3,"pull":3}', 'Horror Factor is 12 against those who know her reputation as a sadistic killer. +9 to save vs magic, +3 vs psionics, +9 vs Horror Factor.', '[{"name":"Literacy: Dragonese/Elf","pct":98},{"name":"Literacy: Demongogian","pct":98},{"name":"Literacy: Creole","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: American","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Land Navigation","pct":97},{"name":"Detect Concealment","pct":88},{"name":"Detect Ambush","pct":93},{"name":"Wilderness Survival","pct":93},{"name":"Dance","pct":93},{"name":"Horsemanship","pct":98},{"name":"Pilot: Flying Platform","pct":98},{"name":"Tracking","pct":88},{"name":"Prowl","pct":88}]', 'Hand to Hand: Assassin, plus Boxing. W.P.s: Sword, Knife, Blunt, Archery and Targeting, Energy Pistol, Energy Rifle.', 'Sees the invisible, nightvision 200 feet (61 m); poisons, drugs and toxins are half as effective; fire and cold do half damage; regenerates 1D6x5 M.D.C. per minute; fires an energy blast.', 'None.', 'None.', NULL, NULL, 'A Sword of Atlantis (a greatest rune weapon) always at her side, plus assorted energy weapons, vibro-blades and torture instruments. Black demon-motif plate armor with 120 M.D.C.', NULL, 'Savagely violent and sadistic behind an unfailing, charming smile; delights in suffering, and her slaves rarely survive more than a month or two. Hawkish, she wants Cibola to go to war, which Inix does not.', 'Inix, who admires her fierceness; she respects Malkhom.', 'Rendell despises her and she holds him in contempt. Rumoured to be weighing whether to replace Inix.', 'A godling of unknown origin - rumour calls her a daughter of Hel, a Persian renegade or a demi-demon - who won the post of War Chief by beheading her predecessor in an arena duel and rules Cibola''s armies harshly. A pale, black-haired woman with deep-blue eyes, dressed always in black.', 'Rifts World Book 6: South America p.130-131'),
('rendell', 'Rendell', NULL, 'The Slave Master; runs Cibola''s slave and drug operations', 'rifts', 'Fire Dragon (adult)', 'Equal to a 10th level ley line walker', 10, 'Aberrant', NULL, NULL, NULL, '{"IQ":21,"ME":14,"MA":19,"PS":30,"PP":19,"PE":23,"PB":18,"Spd":100}', NULL, NULL, 2000, 300, 100, NULL, 16, '{"attacks":8,"initiative":1,"strike":6,"parry":5,"dodge":5,"roll":3,"pull":3}', 'Spd is 100 running or 180 flying. Per melee: 8 hand to hand attacks, 4 fire breaths plus 4 physical, or 2 by magic. +7 to save vs magic, +3 vs psionics, +3 vs Horror Factor.', NULL, 'No skills printed.', 'Nightvision 100 feet (30.5 m), sees the invisible, turns invisible at will, regenerates 1D4x10 M.D. every minute, fire does him no harm, teleport self 88%, dimensional teleport 32%, Metamorphosis at will lasting 40 hours; fire breath.', 'All spell magic levels 1-7, plus Animate and Control Dead, Turn Dead, Exorcism, Resurrection and Remove Curse.', 'All Sensitive and Physical powers.', NULL, NULL, 'None; relies on his natural abilities and wears no armor.', NULL, 'Fawning and servile toward Inix and anyone he sees as a superior, including Malkhom, but his old pride returns with peers and underlings. Unstable from centuries of torture, he regards Inix as a heavenly deliverer, uses dragon-strength narcotics, and is jealous of anyone who draws Inix''s attention.', 'Inix, his rescuer; some loyalty to Malkhom, who has shown him compassion; works alongside Kastor.', 'Despises Iridna.', 'A fire dragon once imprisoned and tortured for centuries by a great horned dragon until Inix slew his captor and freed him. Now an efficient administrator of Cibola''s slave and drug trade. A scarlet dragon covered in unhealed scars; in other shapes he prefers to look like a giant Gatherer.', 'Rifts World Book 6: South America p.131-132'),
('kastor', 'Kastor', NULL, 'Leader of the Gatherers; the Chief Gatherer of Cibola', 'rifts', 'Gatherer', '14th level Gatherer', 14, 'Miscreant', NULL, NULL, NULL, '{"IQ":23,"ME":18,"MA":11,"PS":23,"PP":17,"PE":22,"PB":3,"Spd":15}', NULL, NULL, 600, 264, 112, NULL, 13, '{"attacks":5,"strike":3,"parry":4,"dodge":4,"roll":1,"pull":1}', 'Per melee: 5 hand to hand, 3 psionic, or 2 magic attacks. No initiative bonus printed. +4 to save vs poison, +4 vs magic, +3 vs psionics, +4 vs Horror Factor.', '[{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: Demongogian","pct":98},{"name":"Language: Creole","pct":98},{"name":"Language: American","pct":98},{"name":"Language: Ancient Greek","pct":98},{"name":"Language: Galactic Trade Tongue I","pct":98},{"name":"Language: Galactic Trade Tongue II","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Track Animals","pct":98},{"name":"Track Humans","pct":98},{"name":"Land Navigation","pct":98},{"name":"Wilderness Survival","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Lore: D-Bee","pct":98}]', 'W.P.s: Energy Pistol, Energy Rifle, Sword. A qualified combat robot pilot (no percentage printed).', 'Nightvision 200 feet (61 m), sees the invisible, invisible at will; regenerates 1D6 M.D.C. an hour. Dimensional teleport: 98% to well-known dimensions, 92% to ones he has visited once, 60% blind to ones Gatherers know of; takes a melee round of concentration, no attacks and -2 to defend. Four arms; his back bristles with the spines old Gatherers grow.', 'All spell magic levels 1-5, plus Fire Ball, Impervious to Energy, Mask of Deceit, Reduce Self, Time Slip, Words of Truth, Agony, Dispel Magic Barrier, Invulnerability, Life Drain, Hallucination, Locate, Metamorphosis: Human, Wisps of Confusion, Metamorphosis: Insect, Anti-Magic Cloud, Time Hole and Close Rift.', 'All Sensitive powers, plus Alter Aura, Ectoplasm, Bio-Manipulation, Empathic Transmission, Group Mind Block, Hypnotic Suggestion, Mind Bolt, Mind Bond, Mind Wipe, P.P.E. Shield, Psi-Shield, Telekinesis (normal and super), Telekinetic Force Field and Telemechanics.', NULL, NULL, 'Assorted energy weapons. Natural carapace; sometimes a personal force field belt (130 M.D.C.).', NULL, 'Greedy, scheming and cowardly in a fair fight; prefers ambush, or teleporting away and returning by surprise. Fights readily when the odds favour him, and is dangerous when cornered or overconfident.', 'Inix, whom he has served for two thousand years; the Gatherers; he works with Rendell. Secretly willing to aid Cibola''s lesser enemies.', 'Resents Malkhom and Inix and has plotted for over a century to hurt both without being exposed.', 'The oldest Gatherer in Cibola and the clan chief who first swore to Inix. He lost the intelligence post to Malkhom but still runs the slave and specimen raids that earn much of the city''s income. A squat, four-armed insect-like creature whose spine-covered back gives him a porcupine look.', 'Rifts World Book 6: South America p.132-134'),
('kharkon-the-undaunted', 'Kharkon the Undaunted', 'Rahkali Kharkon-Rah', 'Kharkon the Conqueror; master of the Black Ship fleet on Nightmare Island', 'rifts', 'Pseudo-demon; a former human shifter/witch fused with the essence of an alien intelligence', '12th level shifter and 8th level witch (special)', 12, 'Diabolic', '97', 'Nearly 7 feet (2.1 m)', NULL, '{"IQ":22,"ME":19,"MA":19,"PS":23,"PP":17,"PE":26,"PB":5,"Spd":32}', NULL, NULL, 1300, 1132, 100, NULL, 14, '{"attacks":7,"initiative":3,"strike":5,"parry":6,"dodge":6,"roll":4,"pull":4}', 'level is the shifter level; he is also an 8th level witch. P.S. and P.E. are supernatural. M.D.C. is before any armor or magic. Hand to Hand: Basic, boosted by the alien intelligence within him. Per melee: 7 hand to hand attacks, or 2 by magic. +8 vs poison and disease, and throws them off ten times faster than a human, +7 vs magic, +6 vs psionics, +10 vs Horror Factor; possession and mind control cannot take him. His true name is a closely guarded secret; he may live 10,000 years or more.', '[{"name":"Astronomy","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Lore: Faerie","pct":98},{"name":"Land Navigation","pct":98},{"name":"Wilderness Survival","pct":98},{"name":"Swimming","pct":98},{"name":"Pilot: Boat, Ship and Sailboat","pct":98},{"name":"Language: Demongogian","pct":98},{"name":"Language: Dragonese","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Language: Ancient Greek/Atlantean","pct":98}]', 'The four languages are memories absorbed from Drekkon, never studied. W.P. Sword and Knife at 12th level; W.P. Energy Rifle at 2nd.', 'Every shifter O.C.C. ability, plus: heals 2D6 M.D.C. each melee round; summons 2D6 lesser demons twice a day (40% success); animates and controls 6D6 dead or commands 1D6x10 rats or mice; invulnerable to fire, including M.D. fire, and to possession. The buried mind of Drekkon the Destroyer stirs within him, bringing flashbacks and, in time, perhaps a voice or a split personality.', 'Knows all spells of levels 1-15 at 8th level proficiency. At 12th level proficiency: Sense P.P.E., Sense Magic, Turn Dead, Trance, Chameleon, Concealment, Shadow Meld, Time Slip, Call Lightning, Constrain Being, Summon and Control Canines, Summon Lesser Being, Close Rift.', 'Minor psionic: Object Read, See the Invisible.', NULL, NULL, 'A seemingly indestructible magic sword. Crusader body armor carrying a 6th level Armor of Ithan enchantment. Twelve demon-crewed Black Ships, with eight more being built on Nightmare Island.', NULL, 'A grim, unshakable conqueror, a fine strategist and a rousing leader who tortures and brainwashes captives without qualm. Favours open battle but can play the politician and values spies and assassins. Curt with underlings; treats only mighty mages, godlings, alien intelligences and adult dragons as near-equals, and dreams of a transdimensional empire centred on Earth.', 'Lord Splynncryth of Atlantis (a tentative trade pact of slaves and booty for weapons and ships); contacts in the Pirate Kingdom; Dalgon, Archill and his demon crews.', NULL, 'A shifter from a medieval magic world who made a pact with the alien intelligence Drekkon the Destroyer; when Drekkon tried to take his body, Kharkon won and was left a demonic being. After conquering nearly all his homeworld, he was hurled with a dozen Black Ships through a Rift to the Bermuda Triangle and now rules Nightmare Island. Demonic face, three rows of needle teeth, silver eyes that glow, and dark, leathery skin.', 'Rifts World Book 6: South America p.160-162'),
('dalgon-the-undying', 'Dalgon the Undying', NULL, 'A Syvan Pirate; captain and third in command of Kharkon''s fleet', 'rifts', 'Syvan (supernatural being)', '10th level Syvan', 10, 'Diabolic', NULL, NULL, NULL, '{"IQ":19,"ME":23,"MA":14,"PS":21,"PP":17,"PE":18,"PB":4,"Spd":6}', NULL, NULL, 400, 30, 230, NULL, 13, '{"attacks":2,"initiative":1,"strike":2,"parry":3,"dodge":3,"roll":3,"pull":3,"damage":6}', 'Combat is Supernatural. Per melee: 2 physical or 3 psionic attacks. Damage is +6 to S.D.C. damage. +6 to save vs magic, +7 vs psionics, +7 vs Horror Factor.', '[{"name":"Horsemanship","pct":98},{"name":"Prowl","pct":80},{"name":"Play Musical Instrument: Violin","pct":98},{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: Human Tongue","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: Creole","pct":98},{"name":"Language: American","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Radio: Basic","pct":98},{"name":"Detect Ambush","pct":95},{"name":"Detect Concealment","pct":90},{"name":"Intelligence","pct":87},{"name":"Boating","pct":95},{"name":"Lore: Demons & Monsters","pct":85}]', 'W.P.s: Sword, Energy Rifle, Blunt. Power Armor: Basic, at 3rd level only.', 'Nightvision to 90 feet (27.4 m), sees the invisible, recognizes and is immune to illusions; senses emotions nearby and can pinpoint their source (80%); senses the supernatural like a Psi-Stalker.', 'None.', 'All Sensitive, Healing and Physical powers, plus Bio-Regeneration (4D6 M.D.C. restored in a minute), Bio-Manipulation, Empathic Transmission, Electrokinesis, Telekinesis, Telekinetic Force Field, Mentally Possess Others, Mind Block Auto-Defense, Mind Bond, Mind Wipe, Psi-Shield and Psi-Sword.', NULL, NULL, 'A greater rune sword. Kittani Explorer Armor (85 M.D.C.) or K-Universal Light Power Armor (200 M.D.C.); lately a Kittani suit painted blue and silver, earlier a captured Coalition Dead Boy suit.', NULL, 'A cold, murderous and power-hungry manipulator and a superb pirate captain, second only to Kharkon. Fascinated by Earth''s technology and techno-wizardry, and enjoys tricking mortals into serving him.', 'Kharkon, for now; their ambitions match.', 'Archill, whom he suspects of spying and hopes to have killed by manipulating heroes into fighting him. Would try to awaken the intelligence inside Kharkon if the Conqueror turned on him.', 'A Syvan undead who joined Kharkon early and rose to command a third of his armada; the only one who dares oppose Kharkon at times, and the only one who knows of the alien intelligence within him. A rotting corpse whose left face is little more than bare skull.', 'Rifts World Book 6: South America p.162-163'),
('archill-the-necromancer', 'Archill the Necromancer', NULL, 'Kharkon''s second in command; a former king in his home dimension', 'rifts', 'Human', '12th level necromancer', 12, 'Diabolic', NULL, NULL, NULL, '{"IQ":17,"ME":13,"MA":15,"PS":11,"PP":16,"PE":18,"PB":8,"Spd":10}', 61, 38, 105, 151, 42, NULL, 10, '{"attacks":4,"strike":2,"parry":3,"dodge":3,"roll":4,"pull":4}', 'M.D.C. is the printed total of his gear: 50 from dragon claws and skull worn through Union with the Dead, plus Crusader body armor at 55, plus magic. Hand to Hand: Basic. Per melee: 4 hand to hand attacks, or 2 by magic. No initiative bonus printed. +2 to save vs poison, +3 vs magic, +6 vs Horror Factor.', '[{"name":"Language: Human Tongue","pct":98},{"name":"Language: Dragonese/Elf","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Wilderness Survival","pct":98},{"name":"Skin and Prepare Animal Hides","pct":98},{"name":"Horsemanship","pct":98},{"name":"Pilot: Sailboats","pct":98},{"name":"Disguise","pct":88},{"name":"Intelligence","pct":63},{"name":"First Aid","pct":98},{"name":"Prowl","pct":93},{"name":"Fishing","pct":98}]', 'Human Tongue is the language of his native dimension. Skin and prepare animal hides is printed as hides and bones; the sail skill as boat: sail. W.P.s: Sword, Knife. Refuses to touch a gun.', 'Standard necromancer powers (Rifts Africa): Union with the Dead, augmentation and extra appendages, animates and controls the dead; vampires'' bite and mind control do not affect him.', 'Necromantic spells (Rifts Africa): Command Ghouls, Consume Power and Knowledge, Death Strike, Maggots, Shadow of Doom, Strength of the Dead, Summon Maggot, Summon Worms of Taut. Other spells: Death Trance, Sense Magic, Concealment, Fear, Ley Line Transmission, Shadow Meld, Circle of Flame, Constrain Being, Life Drain, Spoil, Protection Circle: Simple, Banishment, Control/Enslave Entity, Create Mummy, Create Zombie.', 'Minor psionic: Psychic Surgery, Bio-Regeneration.', NULL, NULL, 'An evil-aligned lesser rune sword with all standard abilities; a TW lightning rod. Crusader body armor (55 M.D.C.), though he prefers a pair of adult dragon claws plus a dragon skull that add 50 M.D.C. when activated. Black silk clothes and a flowing black cloak.', NULL, 'A sadist and unrivalled torturer who vents his frustration on the helpless, questioning victims in a quiet, polite voice. Plays the loyal advisor to Kharkon to perfection while waiting for a chance to strike.', 'Agents of Lord Splynncryth of Atlantis, for whom he spies on Kharkon in hope of being sent home by a Stone Master.', 'Kharkon, whom he blames for his exile; Dalgon the Undying, whom he hates.', 'A necromancer who ruled a nation in Kharkon''s home dimension and became his second in command intending to usurp him, only to be stranded on Rifts Earth with him. Conservative and repelled by technology. Pale, hairless and cold to the touch, with flashing black eyes; standing still he can pass for a corpse.', 'Rifts World Book 6: South America p.163-165');
